["displayText"] = "%c",
["customText"] = "function()\n    local currXP, nextXP = GetPetExperience()\n    local PetLevel = UnitLevel(\"pet\")\n    local PlayerLevel = UnitLevel(\"player\")\n    local happiness, damagePercentage, loyaltyRate = GetPetHappiness()\n    local PetExp = nextXP - currXP\n    local state = \"\"\n    --Below is if I want to use loyalty in future\n    --local petLoyaltyText = GetPetLoyalty();\n    \n    --Pet Level Info\n    if PetLevel == PlayerLevel then\n        PetMax = PetLevel..\" (Max)\"\n        Petlvl =  \"0\"\n    else\n        PetMax = PetLevel\n        Petlvl = PetExp\n    end\n    \n    --Happiness Info (Borrowed from \"user\")\n    if happiness then\n        if happiness == 3 then\n            state = \"|CFF20C000快乐\"\n            state = \"\"\n            \n        elseif happiness == 2 then\n            state = \"|CFFFE8A0E满足\"\n        else\n            state = \"|CFFFF0303不高兴\"\n        end\n        \n    end     \n    \n    --Return text\n    return \"|CFFFFFFFF\\n\"..state\nend",
