},
["uid"] = "XqrabAnYj2f",
["useCooldownModRate"] = true,
["cooldownTextDisabled"] = false,
["zoom"] = 0,
["semver"] = "2.0.27",
["tocversion"] = 30400,
["id"] = "General Options - Warlock",
["animation"] = {
["start"] = {
["easeStrength"] = 3,
["type"] = "none",
["duration_type"] = "seconds",
["easeType"] = "none",
},
["main"] = {
["easeStrength"] = 3,
["type"] = "none",
