["init"] = {
["custom"] = "--Zone Dispatcher Init\naura_env.sEventName = \"MultiDotFrame_ChangeZone\"\naura_env.tLastZoneData = nil\naura_env.iLastEncounter = 0\naura_env.iCurrentEncounter = 0\naura_env.tLocalizedZones = {} -- Generated\n\nlocal function HandleEncounterEnd(...)\n    local tZoneData = aura_env.tLocalizedZones[aura_env.sLastZone]\n    if tZoneData == nil then return false end\n    \n    local iEncID = select(1, ...)\n    local iSuccess = select(5, ...)\n    if iSuccess == 1 then\n        if tZoneData and tZoneData[\"Encounters\"] ~= nil and tZoneData[\"Encounters\"][iEncID] ~= nil and tZoneData[\"Encounters\"][iEncID].iNextEncounter ~= nil then\n            aura_env.iCurrentEncounter = tZoneData[\"Encounters\"][iEncID].iNextEncounter   \n        end\n    else\n        aura_env.iCurrentEncounter = iEncID\n    end\n    \n    return true\nend\naura_env.fnHandleEncounterEnd = HandleEncounterEnd\n\n-- On mouseover attempt to find a matching NPC and load its frames\nlocal function HandleMouseoverChanged(...)\n    local tZoneData = aura_env.tLocalizedZones[aura_env.sLastZone]\n    if tZoneData == nil then return false end\n    if UnitIsDead(\"mouseover\") then return false end\n    \n    local sMouseoverGUID = UnitGUID(\"mouseover\") or \"\"\n    local sMouseoverNPCID = select(6, strsplit(\"-\", sMouseoverGUID))\n    if sMouseoverNPCID and tZoneData[\"Encounters\"] ~= nil then\n        for iEncID, tEncData in pairs(tZoneData[\"Encounters\"]) do\n            if type(tEncData) == \"table\" then\n                for sFrameID, tFrameData in pairs(tEncData) do\n                    if type(tFrameData) == \"table\" then\n                        if tFrameData.sNPCID == sMouseoverNPCID then \n                            aura_env.iCurrentEncounter = iEncID\n                            return\n                        end\n                    end\n                end\n            end\n        end\n    end\nend\naura_env.fnHandleMouseoverChanged = HandleMouseoverChanged\n\nlocal function GetZoneData()\n    local sNewZone = GetSubZoneText()\n    if sNewZone == \"\" then \n        sNewZone = GetZoneText()\n    end\n    local tZoneData = aura_env.tLocalizedZones[sNewZone]\n    if tZoneData and tZoneData[\"Encounters\"] ~= nil then\n        tZoneData = tZoneData[\"Encounters\"][aura_env.iCurrentEncounter] or tZoneData[\"Encounters\"][tZoneData[\"Encounters\"].iStartingFight]\n    end\n    \n    return sNewZone, tZoneData\nend\naura_env.fnGetZoneData = GetZoneData\n\nlocal function BroadcastZoneData(sEvent, sNewZone, tZoneData)\n    if aura_env.sLastZone ~= sNewZone or aura_env.iLastEncounter ~= aura_env.iCurrentEncounter or sEvent == \"MultiDotFrame_ZoneData_LateInit\" then -- Force update on entering world, as sLastZone could be based on a STATUS called that happened before everything was loaded \n        if tZoneData ~= nil then \n            WeakAuras.ScanEvents(aura_env.sEventName, sNewZone, tZoneData)\n            aura_env.iIcon = tZoneData.iIcon\n        else\n            WeakAuras.ScanEvents(aura_env.sEventName, sNewZone, nil)\n        end\n    end\nend\naura_env.fnBroadcastZoneData = BroadcastZoneData\n\n",
