["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["use_alwaystrue"] = true,
["custom_type"] = "status",
["unit"] = "player",
["event"] = "Conditions",
["use_unit"] = true,
["subeventPrefix"] = "SPELL",
["custom"] = "-- Zones Dispatcher Trigger\nfunction(sEvent, ...)\n    if aura_env.config.bDebug then\n        print(\"Data\", sEvent, ...)\n    end\n    if sEvent == \"STATUS\" or sEvent == \"PLAYER_ENTERING_WORLD\" then\n        -- Delay Init on Stats/Enter world to ensure everything else is properly init first\n        C_Timer.NewTimer(0.1, function() WeakAuras.ScanEvents(\"MultiDotFrame_ZoneData_LateInit\") end) \n    elseif sEvent == \"MultiDotFrame_Localize\" then \n        aura_env.tLocData = select(1, ...)\n        if aura_env.tZonesData then\n            aura_env.tLocalizedZones = aura_env.tLocData.fnLocalizeTable(aura_env.tZonesData.tZones)\n            --print(dump(aura_env.tLocalizedZones))\n        end\n    elseif sEvent == \"MultiDotFrame_ZonesData\" then\n        aura_env.tZonesData = select(1, ...)\n        if aura_env.tLocData then\n            aura_env.tLocalizedZones = aura_env.tLocData.fnLocalizeTable(aura_env.tZonesData.tZones)\n        end\n    elseif sEvent == \"ENCOUNTER_END\" then\n        return aura_env.fnHandleEncounterEnd(...)\n    end\n    \n    if InCombatLockdown() then \n        -- In combat - keep current result to avoid messing with SecureFrame\n        return aura_env.bLastResult\n    elseif sEvent == \"UPDATE_MOUSEOVER_UNIT\" then\n        aura_env.fnHandleMouseoverChanged(...)   \n    end\n    \n    local sNewZone, tZoneData = aura_env.fnGetZoneData()\n    aura_env.fnBroadcastZoneData(sEvent, sNewZone, tZoneData)\n    \n    aura_env.iLastEncounter = aura_env.iCurrentEncounter\n    aura_env.sLastZone = sNewZone\n    aura_env.tLastZoneData = tZoneData\n    aura_env.bLastResult = (tZoneData ~= nil)\n    return aura_env.bLastResult\nend\n\n\n",
