["height"] = 1,
["width"] = 2,
["useHeight"] = false,
},
{
["desc"] = "|cFF6666FFClassic Skin|r : Progress bars showing the status of all DoTs in a visual way.|n|cFF66FF66Alternative Skin|r : Made by Solah. More compact and uses Icons to display the status of DoTs.",
["type"] = "select",
["values"] = {
"Classic",
"Alternative",
},
["default"] = 1,
["key"] = "iSkin",
["useDesc"] = true,
["name"] = "Skin",
["width"] = 2,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- This WA is used to handle trigger logic of the HP Bars at a single location.\n\nlocal tHPBarTrigger = {}\n\n\nlocal function HandleChangeZone(allStates, ...)\n    local tZoneData = select(2, ...)\n    if tZoneData == nil or tZoneData[aura_env.sFrameID] == nil then return false end\n    aura_env.tZoneData = tZoneData[aura_env.sFrameID]\n    aura_env.sNPCID = aura_env.tZoneData.sNPCID\n    if aura_env.tData then\n        aura_env.tData.fnResetHPBar(allStates)\n        aura_env.tData.CheckNameplatesForNPC(allStates)\n        return true    \n    end\nend\n\nlocal function HandleUpdateHealth(allStates, ...)\n    local sUnitNPCID = select(1, ...)\n    if sUnitNPCID == aura_env.sNPCID then \n        local sUnit = select(2, ...)\n        return aura_env.tData.fnAddHealthBar(allStates, sUnit)\n    end\nend\n\nlocal function HandleCLEU(allStates, ...)\n    local sSubEvent = select(2, ...)\n    if sSubEvent == \"UNIT_DIED\" then\n        local sUnitGUID = select(8, ...)\n        if sUnitGUID then\n            local sUnitNPCID = select(6, strsplit(\"-\", sUnitGUID))\n            if sUnitNPCID == aura_env.sNPCID then \n                aura_env.tData.fnKillHPBar(allStates)\n                return true\n            end\n        end\n    end\nend\n\nlocal function HandleTrigger(allStates, sEvent, ...)\n    if aura_env.tTriggerData.iSkin ~= aura_env.iSkinID then return false end\n    if sEvent == \"MultiDotFrame_ChangeZone\" then\n        return HandleChangeZone(allStates, ...)\n    elseif sEvent == \"MultiDotFrame_UpdateHealth\" then\n        return HandleUpdateHealth(allStates, ...)\n    elseif sEvent == \"NAME_PLATE_UNIT_ADDED\" then\n        local sUnit = select(1, ...)\n        if aura_env.tData.AttemptToAddUnitHealthbar(allStates, sUnit) then\n            return true    \n        end\n    elseif sEvent == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        return HandleCLEU(allStates, ...)\n    elseif sEvent == \"UNIT_HEALTH\" then\n        local sUnit = select(1, ...)\n        if sUnit then\n            return aura_env.tData.fnUpdateHPBar(allStates, sUnit)\n        end\n    end\n    return false\nend\ntHPBarTrigger.fnHandleTrigger = HandleTrigger \n\nlocal function Init()\n    tHPBarTrigger.iSkin = aura_env.config.iSkin\n    WeakAuras.ScanEvents(\"MultiDotFrame_InitSharedTrigger_HPBars\", tHPBarTrigger)\nend\naura_env.fnInit = Init\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
