["Fojji - Drain Soul Snapshot Helper"] = {
["sparkWidth"] = 10,
["iconSource"] = -1,
["wagoID"] = "DiSLra9PF",
["parent"] = "Fojji - DS Snapshotter（痛苦术吸魂分段提示）",
["preferToUpdate"] = false,
["customText"] = "function()\n    local _, classId = UnitClassBase(\"player\");\n    \n    if aura_env.total and classId == 9 then \n        aura_env.delta = aura_env.calculateLive() - aura_env.total\n    end\n    \n    if aura_env.delta == 0 or not aura_env.delta then return \"\" end\n    \n    local format_string\n    if aura_env.delta > 600 then\n        format_string = \"|cFF00FF00%s|r\"..\" dps\"\n    elseif aura_env.delta > 400 then\n        format_string = \"|cFF70FF4e%s|r\"..\" dps\"\n    elseif aura_env.delta > 200 then\n        format_string = \"|cFF77FF71%s|r\"..\" dps\"\n    elseif aura_env.delta > 0 then\n        format_string = \"|cFF76FF76%s|r\"..\" dps\"\n    elseif aura_env.delta < 0 then\n        format_string = \"|cFFFF0000%s|r\"..\" dps\"\n    end\n    return string.format(format_string, aura_env.delta)\nend",
["yOffset"] = -110,
["anchorPoint"] = "CENTER",
["sparkTexture"] = "Interface\\CastingBar\\UI-CastingBar-Spark",
["sparkRotation"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.ds = GetSpellInfo(47855)\naura_env.dsStart = 0\naura_env.delta = 0\naura_env.spProc = 0\n\naura_env.procTrinkets = {\n    [60494] = 765, -- Dying Curse\n    [60064] = 590, -- Sundial of the Exiled\n    [64713] = 959, -- Flare of the Heavens\n}\n\nlocal spellCoefficient = 0.429\nlocal coefficientTotal = 2.145\nlocal shadowMastery = 1.15\nlocal deathsEmbrace = 1.12\nlocal drainSoulModifier = 4\nlocal baseDS = 840\n\nfunction aura_env.getCurrentValues()\n    local spellPower = GetSpellBonusDamage(6)\n    local _,_,_,_,_,_,varmodapplied = UnitDamage(\"player\")\n    local mod = varmodapplied\n    local _,_,_,sbCastTime = GetSpellInfo(6215)\n    local dsChannel = (sbCastTime / 1000) * 10\n    \n    return spellPower, mod, dsChannel\nend\n\nfunction aura_env.calculateStore()\n    local spellPower, mod, dsChannel = aura_env.getCurrentValues()\n    aura_env.spellPowerStore = spellPower - aura_env.spProc\n    \n    local spellDamage = aura_env.spellPowerStore * coefficientTotal\n    local snappedDamage = (baseDS + spellDamage) * shadowMastery * deathsEmbrace * drainSoulModifier * mod\n    local total = snappedDamage / dsChannel\n    \n    return math.floor(total)\nend\n\nfunction aura_env.calculateLive()\n    local spellPower, mod, dsChannel = aura_env.getCurrentValues()\n    \n    local spellDamage = spellPower * coefficientTotal\n    local snappedDamage = (baseDS + spellDamage) * shadowMastery * deathsEmbrace * drainSoulModifier * mod\n    local total = snappedDamage / dsChannel\n    \n    return math.floor(total)\nend\n\nfunction aura_env.HauntCastTime()\n    local _,_,_,GCD = GetSpellInfo(6215)\n    if not GCD then GCD = 1.5 end\n    return GCD/1000\nend",
["do_custom"] = true,
},
