},
["subeventPrefix"] = "SPELL",
["events"] = "PROC_CHECK CLEU:SPELL_AURA_APPLIED CLEU:SPELL_AURA_REMOVED",
["names"] = {
},
["custom"] = "function(event, _, subevent, _, _, sourceName, _, _, destGUID, destName, _, _, spellId, spellName)\n    \n    if subevent == \"SPELL_AURA_APPLIED\" and destName == UnitName(\"player\") then\n        if aura_env.procTrinkets[spellId] then\n            aura_env.spProc = aura_env.procTrinkets[spellId]\n            return true\n        end\n        aura_env.total = aura_env.calculateStore()\n        return true\n    end\n    \n    if subevent == \"SPELL_AURA_REMOVED\" and destName == UnitName(\"player\") then\n        if aura_env.procTrinkets[spellId] then\n            aura_env.spProc = 0\n            return true\n        end\n        return true\n    end\nend",
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
