["dynamicDuration"] = false,
["custom"] = "function(event, _, subevent, _, _, sourceName, _, _, destGUID, destName, _, _, spellId, spellName)\n    \n    if subevent == \"SPELL_CAST_SUCCESS\" and spellName == aura_env.ds and sourceName == UnitName(\"player\") then\n        aura_env.dsStart = GetTime()\n    end\n    \n    if ((subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_REFRESH\") and spellId == 59164 and sourceName == UnitName(\"player\")) or \n    (subevent == \"SPELL_CAST_SUCCESS\" and spellName == aura_env.ds and sourceName == UnitName(\"player\")) then\n        local hauntExists = WA_GetUnitDebuff(\"target\", \"Haunt\", \"PLAYER\")\n        if hauntExists then\n            local expirationTime = select(6, WA_GetUnitDebuff(\"target\", \"Haunt\", \"PLAYER\"))\n            local hauntDebuffTime = expirationTime - GetTime()\n            local _,_,_,fearCastTime = GetSpellInfo(6215)\n            local dsSinceCast = GetTime() - aura_env.dsStart\n            local dsChannel = (fearCastTime / 1000) * 10 -- fojji wtf\n            local _,Max = WeakAuras.GetRange(\"target\")\n            local castTime = aura_env.HauntCastTime()\n            local _,_,_,MS = GetNetStats()\n            local hauntTime = 0.058 * Max + castTime + MS / 1000\n            local relativeTick = dsChannel - dsSinceCast - hauntDebuffTime + hauntTime\n            local tick = aura_env.region.subRegions[3]\n            tick:SetTickPlacement(relativeTick)\n            --print(\"channel =\",dsChannel)\n        end\n    end\nend\n\n\n\n",
