["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- This WA is used to Init the Borders at a single location.\nlocal sEventName_AttemptTarget_Cancel = \"MultiDotFrame_AttemptTarget_Cancel\"\n\nlocal tBorderData = {}\naura_env.tBorderData = tBorderData\n\nlocal function SetIsTargeted()\n    local sGUID = UnitGUID(\"target\")\n    if sGUID then\n        local sTargetNPCID = select(6, strsplit(\"-\", sGUID))\n        if sTargetNPCID == aura_env.sNPCID then \n            aura_env.iIsTargeted = 1   \n        else\n            aura_env.iIsTargeted = 0\n        end\n    else\n        aura_env.iIsTargeted = 0\n    end \nend\ntBorderData.fnSetIsTargeted = SetIsTargeted\n\nlocal function AttemptedToTarget()\n    local bFailedTarget = true\n    local sGUID = UnitGUID(\"target\")\n    if sGUID then\n        local sTargetNPCID = select(6, strsplit(\"-\", sGUID))\n        if sTargetNPCID == aura_env.sNPCID then \n            bFailedTarget = false\n        end\n    end\n    if bFailedTarget then\n        aura_env.bFailedToTarget = 1   \n        C_Timer.NewTimer(0.1, function() WeakAuras.ScanEvents(sEventName_AttemptTarget_Cancel, aura_env.sFrameID) end)\n    end\nend\ntBorderData.fnAttemptedToTarget = AttemptedToTarget\n\nlocal function InitBorderDuplicateData()\n    -- Care - This could be called after the values have already been initialized, depending on the order in which the Init and the ZoneChanged events are received. Don't override anything that isn't nil\n    if aura_env.sNPCID == nil then aura_env.sNPCID = \"\" end\n    if aura_env.iIsTargeted == nil then aura_env.iIsTargeted = 0 end\n    if aura_env.bFailedToTarget == nil then aura_env.bFailedToTarget = 0 end\nend\ntBorderData.fnInitDuplicateData = InitBorderDuplicateData\n\nlocal function Init()\n    WeakAuras.ScanEvents(\"MultiDotFrame_InitBorders\", tBorderData)\nend\naura_env.fnInit = Init\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
