["init"] = {
["custom"] = "--Class Formatter Init\naura_env.sClassName = select(2, UnitClass(\"player\"))\n\nlocal function GetSpellInfos(sSpellName)\n    return aura_env.tAuraData.tSpellsInfos[sSpellName]\nend\n\n-- Checks if a glyph is equipped\nlocal function CheckForGlyph(iGlyphID)\n    for i = 1, GetNumGlyphSockets() do\n        local enabled, _, _, glyphSpellID, _ = GetGlyphSocketInfo(i)\n        if enabled and glyphSpellID == iGlyphID then\n            return true\n        end\n    end\n    return false\nend\n\nlocal function HandleRefreshTalents(tSpell)\n    if tSpell.tRefreshAura then\n        if tSpell.tRefreshAura.tRefreshTalent then \n            tSpell.tRefreshAura.bEnabled = (select(5, GetTalentInfo(tSpell.tRefreshAura.tRefreshTalent.iRow, tSpell.tRefreshAura.tRefreshTalent.iIndex)) > 0)\n        elseif tSpell.tRefreshAura.tRefreshGlyph then\n            tSpell.tRefreshAura.bEnabled = CheckForGlyph(tSpell.tRefreshAura.tRefreshGlyph.iGlyphID)\n        else\n            tSpell.tRefreshAura.bEnabled = true\n        end    \n    end\nend\nlocal function HandleIncreaseDurationGlyphs(tSpell)\n    if tSpell.tIncreaseDurationAura then\n        if tSpell.tIncreaseDurationAura.iGlyphID then \n            tSpell.tIncreaseDurationAura.bEnabled = CheckForGlyph(tSpell.tIncreaseDurationAura.iGlyphID)\n        end    \n    end\nend\n\nlocal function CheckForSet(tSetData)\n    local iEquipped = 0\n    for _,v in ipairs(tSetData.tItems) do\n        if IsEquippedItem(v) then\n            iEquipped = iEquipped + 1\n        end\n    end\n    return (iEquipped >= tSetData.iItemCount)\nend\n\n-- Based on a table containing the different duration for each talent point,  looks up the number of points and returns the corresponding duration\nlocal function CalculateDurationFromTalents(tAuraTable)\n    local iFinalDuration = tAuraTable.iDuration \n    if tAuraTable.iTalentedDuration ~= nil then\n        local iPoints = (select(5, GetTalentInfo(tAuraTable.iTalentedDuration.iTalentPage, tAuraTable.iTalentedDuration.iTalentID)))\n        if iPoints > 0 and tAuraTable.iTalentedDuration.tIncDurations[iPoints] ~= nil then\n            iFinalDuration = iFinalDuration + tAuraTable.iTalentedDuration.tIncDurations[iPoints]\n        end\n    end  \n    if tAuraTable.tGlyphDuration ~= nil then\n        if CheckForGlyph(tAuraTable.tGlyphDuration.iGlyphID) then\n            iFinalDuration = iFinalDuration + tAuraTable.tGlyphDuration.iExtraDuration\n        end\n    end  \n    \n    if tAuraTable.iSetBonusDuration ~= nil then\n        if CheckForSet(tAuraTable.iSetBonusDuration) then \n            iFinalDuration = iFinalDuration + tAuraTable.iSetBonusDuration.iIncDuration\n        end\n    end\n    return iFinalDuration\nend\n\n-- Debug only - prints out the list of talents with their ID to help setup  talent-based spells\nlocal function PrintTalents()\n    local numTabs = GetNumTalentTabs()\n    for t=1, numTabs do\n        DEFAULT_CHAT_FRAME:AddMessage(GetTalentTabInfo(t)..\":\");\n        local numTalents = GetNumTalents(t);\n        for i=1, numTalents do\n            local nameTalent, _, _, _, currRank, maxRank= GetTalentInfo(t,i);\n            DEFAULT_CHAT_FRAME:AddMessage(i .. \"- \"..nameTalent..\": \"..currRank..\"/\"..maxRank);\n        end\n    end    \nend\nlocal function PrintGlyphs()\n    for i = 1, NUM_GLYPH_SLOTS do\n        local enabled, _, _, glyphSpellID, _ = GetGlyphSocketInfo(i);\n        if ( enabled ) then\n            local link = GetGlyphLink(i);-- Retrieves the Glyph's link (\"\" if no glyph in Socket);\n            if ( link ~= \"\") then\n                DEFAULT_CHAT_FRAME:AddMessage(\"Glyph Socket \"..i..\" contains \"..link .. \"(\" .. glyphSpellID .. \")\");\n            else\n                DEFAULT_CHAT_FRAME:AddMessage(\"Glyph Socket \"..i..\" is unlocked and empty!\");\n            end\n        else\n            DEFAULT_CHAT_FRAME:AddMessage(\"Glyph Socket \"..i..\" is locked!\");\n        end\n    end    \nend\n\n-- Handle Refresh/Increased durations based on spell damage - should they be enabled by some talents or glyphs picked?\nlocal function HandleRefreshAndIncreasedDurationOnTable(tData)\n    for _,v in pairs(tData) do \n        HandleRefreshTalents(v)\n        HandleIncreaseDurationGlyphs(v)\n    end\nend\n\n-- Looks up talents and glyphs to setup the the right duration on auras + estimate if they can be refreshed by some spells and affected by haste\nlocal function CheckTalentsAndGlyphs()\n    --PrintTalents()   \n    --PrintGlyphs()\n    aura_env.bHasRefreshedTalents = true\n    \n    -- Handle Refresh/Increased durations based on spell damage - should they be enabled by some talents or glyphs picked?\n    HandleRefreshAndIncreasedDurationOnTable(aura_env.tAuraData.tDamageInfos)\n    HandleRefreshAndIncreasedDurationOnTable(aura_env.tAuraData.tCastInfos)\n    \n    -- Do my DoTs get affected by haste, and does their duration increased based on talents picked?\n    for _,v in pairs(aura_env.tAuraData.tSpellsInfos) do \n        HandleRefreshTalents(v)\n        if v.bAffectedByHasteFromGlyph ~= nil then \n            v.bAffectedByHaste = CheckForGlyph(v.bAffectedByHasteFromGlyph)\n        end\n        v.iFinalDuration = CalculateDurationFromTalents(v)\n    end\nend\naura_env.fnCheckTalentsAndGlyphs = CheckTalentsAndGlyphs\n\n-- Setup SlotNames that can be shared for spells in the same group or unique for others\nlocal function SetupSpellGroups()\n    for _,v in pairs(aura_env.tAuraData.tSpellsInfos) do \n        if v.sGroup ~= nil then\n            v.sSlotName = v.sGroup    \n        else\n            v.sSlotName = v.sName    \n        end\n    end\nend\n\n-- Remove spells that are blacklisted\nlocal function SetupBlacklist()\n    for _,v in pairs(aura_env.tAuraData.tSpellsInfos) do \n        v.bEnabled = true\n    end\n    \n    if aura_env.tAuraData.tBlacklist then\n        for k,v in pairs(aura_env.tAuraData.tBlacklist) do \n            if v then\n                if aura_env.tAuraData.tSpellsInfos[k] ~= nil then \n                    aura_env.tAuraData.tSpellsInfos[k].bEnabled = false\n                end \n            end\n        end\n    end\nend\n\n-- Retrieve the DoT order from the custom options\nlocal function SetupDoTOrder()\n    if aura_env.tAuraData and aura_env.tAuraData.tForceDoTOrder then\n        for k,v in pairs(aura_env.tAuraData.tForceDoTOrder) do\n            if aura_env.tAuraData.tDotOrderIndices[v] ~= nil then\n                local tSpellInfo = GetSpellInfos(aura_env.tAuraData.tDotOrderIndices[v])\n                if tSpellInfo ~= nil then\n                    tSpellInfo.iOrder = tonumber(k)\n                end\n            end\n        end\n    end\n    --[[\n    for k,v in pairs(aura_env.config.tForceDoTOrder) do\n        if aura_env.tDotOrderIndices[v] ~= nil then\n            local tSpellInfo = GetSpellInfos(aura_env.tDotOrderIndices[v])\n            if tSpellInfo ~= nil then\n                tSpellInfo.iOrder = tonumber(k)\n            end\n        end\n    end\n]]--\nend\n\n-- Setup missing spell data\nlocal function SetupSpellData()\n    if aura_env.tAuraData.tCastTriggers == nil then \n        aura_env.tAuraData.tCastTriggers = {}\n    end\n    if aura_env.tAuraData.tDamageTriggers == nil then \n        aura_env.tAuraData.tDamageTriggers = {}\n    end\n    if aura_env.tAuraData.tDamageInfos == nil then \n        aura_env.tAuraData.tDamageInfos = {}\n    end\n    if aura_env.tAuraData.tCastInfos == nil then \n        aura_env.tAuraData.tCastInfos = {}\n    end\nend\n\nlocal function SendAuraData()\n    WeakAuras.ScanEvents(\"MultiDotFrame_ClassData_Formatted\", aura_env.tAuraData)\nend\n\nlocal function SetupAuraData()\n    SetupSpellData()\n    SetupSpellGroups()\n    SetupBlacklist()\n    SetupDoTOrder()\n    aura_env.tAuraData.fnCheckTalentsAndGlyphs = CheckTalentsAndGlyphs\n    SendAuraData()\nend\naura_env.fnSetupAuraData = SetupAuraData\n\n\n",
["do_custom"] = true,
},
