["init"] = {
["custom"] = "-- This WA is used to Init the HP Bars at a single location.\n\nlocal tHPBarData = {}\naura_env.tHPBarData = tHPBarData\ntHPBarData.fUpdateRate = aura_env.config.fUpdateRate\n\nlocal tSpellsToCheckDist = {\n    [\"WARLOCK\"] = \"Shadow Bolt\",\n    [\"MAGE\"] = \"Living Bomb\",\n}\nlocal sSpellToCheckDist = tSpellsToCheckDist[select(2, UnitClass(\"player\"))] or \"\"\n\nlocal function AddHealthBar(allStates, sUnit)   \n    if not allStates[1] then \n        allStates[1] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            total = 100,\n            inverse = true,\n            value = 100,\n            name = \"???\",\n            bInRange = false,\n            sRaidMarker = nil,\n        }\n        if aura_env.tZoneData then\n            allStates[1].name = aura_env.tZoneData.sTarName\n        end\n    end\n    allStates[1].changed = true\n    \n    if sUnit then\n        local fExecuteRange = aura_env.tData.tClassData and aura_env.tData.tClassData.fExecuteRange or 0\n        local fPct = UnitHealth(sUnit) / UnitHealthMax(sUnit)\n        allStates[1].name = UnitName(sUnit)\n        allStates[1].value = fPct * 100\n        allStates[1].bExecuteRange = (fPct < fExecuteRange)\n        allStates[1].bInRange = IsSpellInRange(sSpellToCheckDist, sUnit) ~= 0\n        local sRaidTarget = GetRaidTargetIndex(sUnit)\n        if sRaidTarget then \n            allStates[1].sRaidMarker = \"{rt\" .. sRaidTarget .. \"} \"\n        else \n            allStates[1].sRaidMarker = \"\"\n        end\n        \n        if fPct <= 0 then \n            tHPBarData.fnKillHPBar(allStates)\n        end\n    end\n    \n    return true\nend\ntHPBarData.fnAddHealthBar = AddHealthBar\n\nlocal function AttemptToAddUnitHealthbar(allStates, sUnit)\n    if UnitExists(sUnit) then \n        local sUnitGUID = UnitGUID(sUnit)\n        local sUnitNPCID = select(6, strsplit(\"-\", sUnitGUID))\n        if aura_env.sNPCID == sUnitNPCID then \n            AddHealthBar(allStates, sUnit)\n            return true\n        end    \n    end\n    \n    return false\nend\ntHPBarData.AttemptToAddUnitHealthbar = AttemptToAddUnitHealthbar\n\nlocal function CheckNameplatesForNPC(allStates)\n    for i = 0, 30 do \n        local sUnit = \"nameplate\" .. i\n        if AttemptToAddUnitHealthbar(allStates, sUnit) then\n            return true    \n        end\n    end\n    AddHealthBar(allStates, nil)\n    return true\nend\ntHPBarData.CheckNameplatesForNPC = CheckNameplatesForNPC\n\nlocal function ResetHPBar(allStates) \n    if allStates[1] then \n        allStates[1].value = 100\n        allStates[1].bInRange = false\n        allStates[1].bExecuteRange = false\n        allStates[1].name = aura_env.tZoneData.sTarName\n        allStates[1].changed = true\n    end    \nend\ntHPBarData.fnResetHPBar = ResetHPBar\n\nlocal function KillHPBar(allStates)\n    allStates[1] = {\n        show = false,\n        changed = true,\n    }\nend\ntHPBarData.fnKillHPBar = KillHPBar\n\nlocal function UpdateHPBar(allStates, sUnit) \n    local sUnitGUID = UnitGUID(sUnit)\n    local sUnitNPCID = select(6, strsplit(\"-\", sUnitGUID))\n    \n    if sUnitNPCID == aura_env.sNPCID and GetTime() > aura_env.fNextUpdate then \n        aura_env.tData.fnAddHealthBar(allStates, sUnit)\n        \n        aura_env.fNextUpdate = GetTime() + aura_env.tData.fUpdateRate\n        return true\n    end\n    return false\nend\ntHPBarData.fnUpdateHPBar = UpdateHPBar\n\nlocal function InitHPBarDuplicateData()\n    -- Care - This could be called after the values have already been initialized, depending on the order in which the Init and the ZoneChanged events are received. Don't override anything that isn't nil\n    if aura_env.sNPCID == nil then aura_env.sNPCID = \"\" end\n    if aura_env.fNextUpdate == nil then aura_env.fNextUpdate = 0 end\nend\n\ntHPBarData.fnInitDuplicateData = InitHPBarDuplicateData\n\nlocal function Init()\n    WeakAuras.ScanEvents(\"MultiDotFrame_InitHPBars\", tHPBarData)\nend\naura_env.fnInit = Init\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
