},
["init"] = {
["do_custom"] = false,
["custom"] = "local e = aura_env \nif not _G[e.id..\"Button\"] then \n    local region = WeakAuras.GetRegion(e.id) \n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\") \n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"RightButtonUp\")\n    e.btn:SetAllPoints(region) \nend \nlocal btn = _G[e.id..\"Button\"] \nlocal m1 =\"/use 法力刚玉\"\nlocal m2 = [=[\n/script for i=0,4 do for j=1,20 do a=GetContainerItemLink(i,j)if a and a:find(\"法力刚玉\")then PickupContainerItem(i,j)DeleteCursorItem()break end end end\n/cast 制造法力宝石\n]=]\n\nbtn:SetAttribute(\"type1\", \"macro\")\nbtn:SetAttribute(\"type2\", \"macro\")\nbtn:SetAttribute(\"macrotext1\", m1)\nbtn:SetAttribute(\"macrotext2\",m2)\nbtn:SetScript(\"OnEnter\", function(self)               \n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\") \n        GameTooltip:SetText(\"|cffffffff左键：|r使用法力刚玉|cff04f192|r\\n|cffffffff右键：|r右键摧毁重做|cff04f192|r\", 0, 1, 0, 1, 1)\nend)\nbtn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\nbtn:Show()",
},
