["trigger"] = {
["spellName"] = {
"Rapture",
},
["type"] = "custom",
["subeventSuffix"] = "_ENERGIZE",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventPrefix"] = "SPELL",
["event"] = "Combat Log",
["names"] = {
},
["spellIds"] = {
},
["use_spellName"] = true,
["custom"] = "function(allstates,event,...)\n    local _, type, _, _, sName, _, _, _, _, _, _, spellID, _, _, _, _, _, _ = ...\n    local amount = select(15, ...)\n    \n    if ((type == \"SPELL_ENERGIZE\") and aura_env.spells[spellID] ~= nil) then\n        local type = aura_env.spells[spellID]\n        if type == \"Rage\" then amount = WrapTextInColorCode(amount..\" \"..type,\"FFFF0000\")\n        elseif type == \"RP\" then amount = WrapTextInColorCode(amount..\" \"..type,\"FF00D1FF\")\n        elseif type == \"Energy\" then amount = WrapTextInColorCode(amount..\" \"..type,\"FFFFFF00\")\n        else amount = WrapTextInColorCode(amount..\" \"..type,\"FF4D85E6\")\n        end\n        allstates[sName] = allstates[sName] or {}\n        local state = allstates[sName]\n        \n        state.unit = sName\n        state.text = amount\n        state.duration = 5\n        state.expirationTime = GetTime() + 5\n        state.changed = true\n        state.show = true\n        state.autoHide = true\n        state.progressType = \"timed\"\n        return true\n    end\nend",
["events"] = "CLEU:SPELL_ENERGIZE",
