["init"] = {
["custom"] = "-- Class Data Priest Init\nlocal tAuraData = {}\nlocal bIsHorde = (UnitFactionGroup(\"player\") == \"Horde\")\naura_env.sPlayerClass = \"PRIEST\"\n\ntAuraData.tDotOrderIndices = {\n    [1] = \"None\", \n    [2] = \"Vampiric Touch\", \n    [3] = \"Shadow Word: Pain\", \n    [4] = \"Devouring Plague\", \n}\n\ntAuraData.tDotAuras = {\n    [34914] = \"Vampiric Touch\",\n    [34916] = \"Vampiric Touch\",\n    [34917] = \"Vampiric Touch\",\n    [48159] = \"Vampiric Touch\",\n    [48160] = \"Vampiric Touch\",\n    [589] = \"Shadow Word: Pain\",\n    [594] = \"Shadow Word: Pain\",\n    [970] = \"Shadow Word: Pain\",\n    [992] = \"Shadow Word: Pain\",\n    [2767] = \"Shadow Word: Pain\",\n    [10892] = \"Shadow Word: Pain\",\n    [10893] = \"Shadow Word: Pain\",\n    [10894] = \"Shadow Word: Pain\",\n    [25367] = \"Shadow Word: Pain\",\n    [25368] = \"Shadow Word: Pain\",\n    [48124] = \"Shadow Word: Pain\",\n    [48125] = \"Shadow Word: Pain\",\n    [2944] = \"Devouring Plague\",\n    [19276] = \"Devouring Plague\",\n    [19277] = \"Devouring Plague\",\n    [19278] = \"Devouring Plague\",\n    [19279] = \"Devouring Plague\",\n    [19280] = \"Devouring Plague\",\n    [25467] = \"Devouring Plague\",\n    [48299] = \"Devouring Plague\",\n    [48300] = \"Devouring Plague\",\n    [15407] = \"Mind Flay\",\n    [17311] = \"Mind Flay\",\n    [17312] = \"Mind Flay\",\n    [17313] = \"Mind Flay\",\n    [17314] = \"Mind Flay\",\n    [18807] = \"Mind Flay\",\n    [25387] = \"Mind Flay\",\n    [48155] = \"Mind Flay\",\n    [48156] = \"Mind Flay\",\n}\ntAuraData.tDamageTriggers = {\n}\n\ntAuraData.tDamageInfos = {\n}\n\ntAuraData.tSpellsInfos = {\n    [\"Shadow Word: Pain\"] = {\n        iDuration = 18,\n        sName = \"Shadow Word: Pain\",\n        iIcon = 136207,\n        iColorR = 1.000,\n        iColorG = 0.647,\n        iColorB = 0.031,\n    },  \n    [\"Vampiric Touch\"] = {\n        iDuration = 15,\n        sName = \"Vampiric Touch\",\n        iIcon = 135978,\n        iColorR = 0.213,\n        iColorG = 0.267,\n        iColorB = 0.945,\n        bAffectedByHaste = true,\n        iSetBonusDuration = {\n            iItemCount = 2,\n            iIncDuration = 6,\n            tItems = {\n                bIsHorde and 48098 or 48073, -- 10 Helm\n                bIsHorde and 48097 or 48072, -- 10 Gloves\n                bIsHorde and 48101 or 48076, -- 10 Shoulders\n                bIsHorde and 48099 or 48074, -- 10 Pants\n                bIsHorde and 48100 or 48075, -- 10 Chest\n                bIsHorde and 48095 or 48078, -- 25 Helm\n                bIsHorde and 48096 or 48077, -- 25 Gloves\n                bIsHorde and 48092 or 48081, -- 25 Shoulders\n                bIsHorde and 48094 or 48079, -- 25 Pants\n                bIsHorde and 48093 or 48080, -- 25 Chest\n                bIsHorde and 48088 or 48085, -- 25H Helm\n                bIsHorde and 48087 or 48086, -- 25H Gloves\n                bIsHorde and 48091 or 48082, -- 25H Shoulders\n                bIsHorde and 48089 or 48084, -- 25H Pants\n                bIsHorde and 48090 or 48083, -- 25H Chest\n            },\n        },\n    },  \n    [\"Devouring Plague\"] = {\n        iDuration = 24,\n        sName = \"Devouring Plague\",\n        iIcon = 252996,\n        iColorR = 0.948,\n        iColorG = 0.047,\n        iColorB = 0.934,\n        bAffectedByHaste = true,\n        bRemoveFromOtherFrames = true,\n    },  \n    [\"Mind Flay\"] = {\n        tRefreshAura = {\n            tRefreshTalent = {\n                iRow = 3,\n                iIndex = 24,\n            },\n            tAuras = {\n                \"Shadow Word: Pain\"\n            }\n        },\n    },  \n}\n\ntAuraData.tCastingModeBindings = aura_env.config.tCastingModeBindings.tPriest\ntAuraData.tBlacklist = aura_env.config.tBlacklist\ntAuraData.tForceDoTOrder = aura_env.config.tForceDoTOrder.tPriest\n\ntAuraData.fExecuteRange = 0\n\nlocal function SendAuraData()\n    WeakAuras.ScanEvents(\"MultiDotFrame_AuraData\", tAuraData, aura_env.sPlayerClass)\nend\n\naura_env.fnSendAuraData = SendAuraData\n\n",
