["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- Class Data Shaman Init\nlocal tAuraData = {}\nlocal bIsHorde = (UnitFactionGroup(\"player\") == \"Horde\")\naura_env.sPlayerClass = \"SHAMAN\"\n\ntAuraData.tDotOrderIndices = {\n    [1] = \"None\", \n    [2] = \"Flame Shock\", \n}\n\ntAuraData.tDotAuras = {\n    [8050] = \"Flame Shock\",\n    [8052] = \"Flame Shock\",\n    [8053] = \"Flame Shock\",\n    [10447] = \"Flame Shock\",\n    [10448] = \"Flame Shock\",\n    [29228] = \"Flame Shock\",\n    [25457] = \"Flame Shock\",\n    [49232] = \"Flame Shock\",\n    [49233] = \"Flame Shock\",\n}\ntAuraData.tDamageTriggers = {\n}\n\ntAuraData.tDamageInfos = {\n}\n\ntAuraData.tSpellsInfos = {\n    [\"Flame Shock\"] = {\n        iDuration = 18,\n        sName = \"Flame Shock\",\n        iIcon = 135813,\n        iColorR = 1.000,\n        iColorG = 0.547,\n        iColorB = 0.247,\n        bAffectedByHaste = true,\n        iSetBonusDuration = {\n            iItemCount = 2,\n            iIncDuration = 9,\n            tItems = {\n                bIsHorde and 48337 or 48312, -- 10 Gloves\n                bIsHorde and 48336 or 48310, -- 10 Chest\n                bIsHorde and 48338 or 48313, -- 10 Helm\n                bIsHorde and 48339 or 48314, -- 10 Pants\n                bIsHorde and 48340 or 48315, -- 10 Shoulders\n                bIsHorde and 48334 or 48317, -- 25 Gloves\n                bIsHorde and 48335 or 48316, -- 25 Chest\n                bIsHorde and 48333 or 48318, -- 25 Helm\n                bIsHorde and 48332 or 48319, -- 25 Pants\n                bIsHorde and 48331 or 48320, -- 25 Shoulders\n                bIsHorde and 48327 or 48324, -- 25H Gloves\n                bIsHorde and 48326 or 48325, -- 25H Chest\n                bIsHorde and 48328 or 48323, -- 25H Helm\n                bIsHorde and 48329 or 48322, -- 25H Pants\n                bIsHorde and 48330 or 48321, -- 25H Shoulders\n            },\n        },\n    },  \n}\n\ntAuraData.tCastingModeBindings = aura_env.config.tCastingModeBindings.tShaman\ntAuraData.tBlacklist = aura_env.config.tBlacklist\ntAuraData.tForceDoTOrder = aura_env.config.tForceDoTOrder.tShaman\n\ntAuraData.fExecuteRange = 0\n\nlocal function SendAuraData()\n    WeakAuras.ScanEvents(\"MultiDotFrame_AuraData\", tAuraData, aura_env.sPlayerClass)\nend\n\naura_env.fnSendAuraData = SendAuraData\n\n",
["do_custom"] = true,
},
