["preferToUpdate"] = true,
["customText"] = "-- Author: 露露緹婭@Bilibili\n-- 更新时间：2025/10/07\n-- 更新国服美酒节特供版饰品（271装等）\nfunction()\n    -- 获取当前触发的法术ID\n    local spellId = aura_env.state and aura_env.state.spellId\n    \n    -- 如果没有法术ID，返回空字符串\n    if not spellId then\n        return \"\"\n    end\n    \n    -- 映射表\n    local RurutiaTexts = {\n        -- 暗月卡牌伟大\n        [60234] = \"智力\",\n        [60235] = \"精神\",\n        [60229] = \"力量\",\n        [60233] = \"敏捷\",\n        \n        -- 增伤类\n        [57933] = \"增伤\",\n        [59628] = \"增伤\",    \n        [49016] = \"增伤\",\n        [55975] = \"增伤\",    \n        [55213] = \"增伤\",    \n        \n        -- 技能效果\n        [60513] = \"减耗\",    \n        [59620] = \"狂暴\",    \n        \n        -- 资源回复\n        [49623] = \"回蓝\",    \n        [64999] = \"回蓝\",    \n        [1247618] = \"回蓝\",  \n        [64739] = \"回蓝\",    \n        \n        -- 战斗效果\n        [60437] = \"破甲\",    \n        [60436] = \"破甲\",    \n        [65020] = \"破甲\",    \n        [65019] = \"破甲\",    \n        [65024] = \"暴击\",    \n        \n        -- 防御类\n        [398478] = \"躲闪\",   \n        [64763] = \"躲闪\",    \n        [1247619] = \"躲闪\",  \n        [1259913] = \"躲闪\", -- 打斗者的纪念品，醉仙步，躲闪（271）\n        \n        -- 武器附魔\n        [53365] = \"十字军\",  \n        [28093] = \"猫鼬\",    \n        \n        -- 特殊装备\n        [64411] = \"橙锤\",    \n        [1249836] = \"黑心\",  \n        [1259888] = \"回血\", -- 光明汽酒咒符，美酒女郎的祝福，回血（271）\n    }\n    \n    -- 查找并返回对应的显示文本\n    return RurutiaTexts[spellId] or \"\"\nend",
["yOffset"] = 0,
