["actions"] = {
["start"] = {
["custom"] = "-- Author: 露露緹婭@Bilibili\n-- 获取当前触发的技能ID\nlocal spellId = aura_env.state and aura_env.state.spellId\nif not spellId or not aura_env.soundMap[tostring(spellId)] then\n    return\nend\n\nlocal spellIdStr = tostring(spellId)\nlocal currentTime = GetTime()\n\n-- 检查是否需要间隔播报\nif aura_env.cooldownConfig[spellIdStr] then\n    local cooldownTime = aura_env.cooldownConfig[spellIdStr]\n    local lastTime = aura_env.lastPlayTime[spellIdStr] or 0\n    \n    -- 如果还在冷却时间内，不播放音效\n    if currentTime - lastTime < cooldownTime then\n        return\n    end\n    \n    -- 更新上次播放时间\n    aura_env.lastPlayTime[spellIdStr] = currentTime\nend\n\n-- 播放音效\nlocal soundFile = aura_env.soundMap[spellIdStr]\nif soundFile then\n    if not soundFile:match(\"^Interface\\\\\\\\\") then\n        soundFile = aura_env.RurutiaVoice .. soundFile\n    end\n    PlaySoundFile(soundFile, \"Master\")\nend",
