["wagoID"] = "5GWfkcgv3",
["parent"] = "牧师 职业分组（by 露露緹婭@Bilibili）1114更",
["customText"] = "function()\n    if not aura_env.last or aura_env.last < GetTime() - .2 then\n        aura_env.last = GetTime()\n        aura_env.critcurrent = GetSpellCritChance(6)\n        \n        for i = 1, 60 do\n            local _,_, count,_,_,_,_,_,_, spellId = UnitDebuff(\"target\", i)\n            if not spellId then break end\n            if spellId == 22959 or spellId == 17800 then -- Shadow Mastery/Improved Scorch\n                aura_env.critcurrent = aura_env.critcurrent + 5\n            end\n            if spellId == 54499 then -- Heart of the Crusader\n                aura_env.critcurrent = aura_env.critcurrent + 3\n            end\n        end\n        \n        local _, _,_,_,_,_,varmodcurrent = UnitDamage(\"player\")\n        aura_env.modcurrent = varmodcurrent\n        \n        for i = 1, 60 do\n            local _,_, count,_,_,_,_,_,_, spellId = UnitBuff(\"player\", i)\n            if not spellId then break end\n            if spellId == 15258 then -- Shadow Weaving\n                aura_env.modcurrent = aura_env.modcurrent + (0.02 * count)\n            end\n        end      \n        \n        aura_env.totalcurrent = (((100* (aura_env.modcurrent))*(100-aura_env.critcurrent)/100)+((100* (aura_env.modcurrent)*2)*(aura_env.critcurrent)/100))\n        aura_env.totaldifference = aura_env.totalcurrent - aura_env.totalapplied\n    end\n    return string.format(\"|cFF%s%s%.1f%%|r\", aura_env.totaldifference > 0 and '22ff43' or aura_env.totaldifference < 0 and 'ff2f2a' or '808080', aura_env.totaldifference > 0 and '+' or '', aura_env.totaldifference)\nend",
["displayText_format_c2_decimal_precision"] = 2,
["cooldownSwipe"] = true,
["customTextUpdate"] = "update",
["automaticWidth"] = "Auto",
["desc"] = "Fojji - Snapshotter\nhttps://wago.io/5GWfkcgv3/1",
["triggers"] = {
{
["trigger"] = {
["duration"] = "18",
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["custom_hide"] = "custom",
["type"] = "custom",
["names"] = {
},
["custom_type"] = "event",
["subeventSuffix"] = "_CAST_SUCCESS",
["custom"] = "function(event, _, subevent, _, _, sourceName, _, _, _, destName, _, _, spellId, spellName)\n    \n    if subevent == \"SPELL_MISSED\" then\n        return false\n    end\n    \n    if subevent == \"SPELL_CAST_SUCCESS\"\n    and spellName == aura_env.swp and sourceName == UnitName(\"player\") then\n        aura_env.critapplied = GetSpellCritChance(6) -- Spell Crit of Shadow School\n        \n        for i = 1, 60 do\n            local _,_, count,_,_,_,_,_,_, spellId = UnitDebuff(\"target\", i)\n            if not spellId then break end\n            if spellId == 22959 or spellId == 17800 then -- Shadow Mastery/Improved Scorch\n                aura_env.critapplied = aura_env.critapplied + 5\n            end\n            if spellId == 54499 then -- Heart of the Crusader\n                aura_env.critapplied = aura_env.critapplied + 3\n            end\n        end\n        \n        local _, _,_,_,_,_,varmodapplied = UnitDamage(\"player\")\n        aura_env.modapplied = varmodapplied\n        \n        for i = 1, 60 do\n            local _,_, count,_,_,_,_,_,_, spellId = UnitBuff(\"player\", i)\n            if not spellId then break end\n            if spellId == 15258 then -- Shadow Weaving\n                aura_env.modapplied = aura_env.modapplied + (0.02 * count)\n            end\n        end       \n        \n        aura_env.totalapplied = (((100*(aura_env.modapplied))*(100-aura_env.critapplied)/\n            100)+((100*(aura_env.modapplied)*2)*(aura_env.critapplied)/100))\n        return true\n    end\nend",
