["custom"] = "-- Loca Data ruRU Init\n-- This WA is only used to localize some of the strings used in other WAs\naura_env.sLocale = \"ruRU\"\n\nlocal tLocData = {}\naura_env.tLocData = tLocData\ntLocData.tLocalizations = {\n    -- Testing\n    [\"The Great Forge\"] =  \"Великая Кузня\",\n    [\"War Quarter\"] = \"Квартал Воинов\",\n    [\"Valley of Honor\"] = nil,\n    [\"Heroic Training Dummy\"] = \"Героический тренировочный манекен\",\n    [\"Grandmaster's Training Dummy\"] = \"Тренировочный манекен великого мастера\",\n    [\"Expert's Training Dummy\"] = \"Тренировочный манекен для опытных бойцов\",\n    [\"Master's Training Dummy\"] = \"Тренировочный манекен для мастеров\",\n    -- Sartharion\n    [\"The Obsidian Sanctum\"] = \"Обсидиановое святилище\",\n    [\"Tenebron\"] = \"Тенеброн\",\n    [\"Shadron\"] = \"Шадрон\",\n    [\"Vesperon\"] = \"Весперон\",\n    -- Naxx\n    [\"The Horsemen's Assembly\"] = nil,\n    [\"Baron Rivendare\"] = \"Барон Ривендер\",\n    [\"Thane Korth'azz\"] = \"Тан Корт'азз\",\n    [\"Lady Blaumeux\"] = \"Леди Бломе\",\n    -- Ulduar\n    [\"Formation Grounds\"] = \"Плац\",\n    [\"Flame Leviathan\"] = \"Огненный Левиафан\",\n    [\"The Colossal Forge\"] = \"Гигантская кузня\",\n    [\"Ignis the Furnace Master\"] = \"Повелитель Горнов Игнис\",\n    [\"Razorscale's Aerie\"] = \"Гнездо Острокрылой\",\n    [\"Razorscale\"] = \"Острокрылая\",\n    [\"The Scrapyard\"] = \"Мусорная свалка\",\n    [\"XT-002 Deconstructor\"] = \"Разрушитель XT-002\",\n    [\"The Celestial Planetarium\"] = \"Священный планетарий\",\n    [\"Algalon the Observer\"] = \"Алгалон Наблюдатель\",\n    [\"The Observation Ring\"] = \"Круг Наблюдения\",\n    [\"Auriaya\"] = \"Ауриайя\",\n    [\"The Halls of Winter\"] = \"Залы Зимы\",\n    [\"Hodir\"] = \"Ходир\",\n    [\"The Clash of Thunder\"] = \"Раскаты Грома\",\n    [\"Thorim\"] = \"Торим\",\n    [\"The Descent into Madness\"] = \"Провал Безумия\",\n    [\"General Vezax\"] = \"Генерал Везакс\",\n    [\"The Prison of