 \n    [\"Saamul\"] = \"Саамул\",\n    [\"Thrakgar\"] = nil,\n    [\"Irieth Shadowstep\"] = \"Ириэт Шаг Сквозь Тень\",\n    [\"Maz'dinah\"] = nil,\n    [\"Shocuul\"] = \"Шокул\",\n    [\"Narrhok Steelbreaker\"] = nil, \n    [\"Alyssia Moonstalker\"] = \"Алисса Лунопард\",\n    [\"Ruj'kah\"] = nil,\n    [\"Tyrius Duskblade\"] = \"Тирий Клинок Сумерек\",\n    [\"Gorgrim Shadowcleave\"] = nil,\n    [\"Serissa Grimdabbler\"] = \"Серисса Мрачная Кропильщица\",\n    [\"Harkzog\"] = nil, \n    [\"Baelnor Lightbearer\"] = \"Бельнор Светоносный\",\n    [\"Malithas Brightblade\"] = nil,\n    [\"Velanaa\"] = \"Веланаа\",\n    [\"Liandra Suncaller\"] = nil,\n    [\"Kavina Grovesong\"] = \"Кавина Песня Рощи\",\n    [\"Birana Stormhoof\"] = nil, \n    [\"Brienna Nightfell\"] = \"Бриенна Приход Ночи\",\n    [\"Vivienne Blackwhisper\"] = nil,\n    [\"Noozle Whizzlestick\"] = \"Нуззл Чудодей\",\n    [\"Ginselle Blightslinger\"] = nil,\n    [\"Fjola Lightbane\"] = \"Фьола Погибель Света\",\n    [\"Eydis Darkbane\"] = \"Эйдис Погибель Тьмы\",\n    [\"The Icy Depths\"] = \"Ледяные глубины\",\n    [\"Anub'arak\"] = \"Ануб'арак\",\n    [\"Nerubian Burrower\"] = \"Нерубский землеглот\",\n    [\"Onyxia's Lair\"] = \"Логово Ониксии\",\n    [\"Onyxia\"] = \"Ониксия\",\n    [\"Onyxian Lair Guard\"] = \"Страж логова Ониксии\",\n    -- ICC\n    [\"The Spire\"] = \"Шпиль\",\n    [\"Lord Marrowgar\"] = \"Лорд Ребрад\",\n    [\"Bone Spike\"] = \"Костяной шип\",\n    [\"Oratory of the Damned\"] = \"Молельня Проклятых\",\n    [\"Lady Deathwhisper\"] = \"Леди Смертный Шепот\",\n    [\"Cult Adherent\"] = \"Приверженец культа\",\n    [\"Cult Fanatic\"] = \"Фанатик культа\",\n    [\"Rampart of Skulls\"] = \"Черепной вал\",\n    [\"Muradin Bronzebeard\"] = \"Мурадин Бронзобород\",\n    [\"High Overlord Saurfang\"] = \"Варок Саурфанг\",\n    [\"Deathbringer's Rise\"] = \"Подъем Смертоносного\",\n    [\"Deathbringer Saurfang\"] = \"Саурфанг Смертоносный\",\n    [\"Blood Beast\"] = \"Кровавое чудовище\",\n    [\"The Plagueworks\"] = \"Чумодельня\",\n    [\"Festergut\"] = \"Тухлопуз\",\n    [\"Rotface\"] = \"Гниломорд\",\n    [\"Little Ooze\"] = \"Малый слизнюк\",\n    [\"Putricide's Laboratory of Alchemical Horrors and Fun\"] = \"Лаборатория алхимических ужасов и забав\",\n    [\"Volatile Ooze\"] = \"Неустойчивый слизнюк\",\n    [\"Professor Putricide\"] = \"Профессор Мерзоцид\",\n    [\"Gas Cloud\"] = \"Облако газа\",\n    [\"The Crimson Hall\"] = \"Багровый зал\",\n    [\"Prince Taldaram\"] = \"Принц Талдарам\",\n    [\"Prince Keleseth\"] = \"Принц Келесет\",\n    [\"Prince Valanar\"] = \"Принц Валанар\",\n    [\"The Sanctum of Blood\"] = \"Святилище Крови\",\n    [\"Blood-Queen Lana'thel\"] = \"Кровавая королева Лана'тель\",\n    [\"The Frostwing Halls\"] = \"Залы Ледокрылых\",\n    [\"Valithria Dreamwalker\"] = \"Валитрия Сноходица\",\n    [\"Gluttonous Abomination\"] = \"Прожорливое поганище\",\n    [\"Risen Archmage\"] = \"Воскрешенный верховный маг\",\n    [\"Suppresser\"] = \"Подавитель\",\n    [\"The Frost Queen's Lair\"] = \"Логово Королевы Льда\",\n    [\"Sindragosa\"] = \"Синдрагоса\",\n    [\"The Frozen Throne\"] = \"Ледяной трон\",\n    [\"The Lich King\"] = \"Король-лич\",\n    [\"Shambling Horror\"] = \"Шаркающий ужас\",\n    [\"Ice Sphere\"] = \"Ледяная сфера\",\n    [\"Raging Spirit\"] = \"Гневный дух\",\n    [\"Val'kyr Shadowguard\"] = \"Валь'кира - страж Тьмы\",\n}\n\n\nlocal function LocalizeTable(tTableToLocalize)\n    if tTableToLocalize.bLocalized then return tTableToLocalize end\n    \n    local tLocalizedTable = {\n        bLocalized = GetLocale(),\n        \n    }\n    \n    local function LocalizeField(tIn, tOut, sKey)\n        local sLocalizedKey = sKey\n        if tLocData.tLocalizations[sKey] and tLocData.tLocalizations[sKey] then\n            sLocalizedKey = tLocData.tLocalizations[sKey]\n        end\n        \n        if type(tIn[sKey]) == \"table\" then\n            tOut[sLocalizedKey] = {}\n            \n            for k,_ in pairs(tIn[sKey]) do\n                LocalizeField(tIn[sKey], tOut[sLocalizedKey], k)\n            end\n        else\n            if tLocData.tLocalizations[tIn[sKey]] and tLocData.tLocalizations[tIn[sKey]] then\n                tOut[sLocalizedKey] = tLocData.tLocalizations[tIn[sKey]]\n            else\n                tOut[sLocalizedKey] = tIn[sKey]\n            end\n        end\n    end\n    \n    for k,_ in pairs(tTableToLocalize) do\n        LocalizeField(tTableToLocalize, tLocalizedTable, k)\n    end\n    \n    return tLocalizedTable\nend\ntLocData.fnLocalizeTable = LocalizeTable\n\nlocal function InitLoca()\n    if GetLocale() == aura_env.sLocale then\n        WeakAuras.ScanEvents(\"MultiDotFrame_Localize\", tLocData)\n    end\nend\naura_env.fnInitLoca = InitLoca\n\nInitLoca()",
