["custom"] = "function(event, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8, arg9, arg10, ...)\n    if event == \"CHAT_MSG_COMBAT_XP_GAIN\" and UnitLevel(\"player\") ~= MAX_PLAYER_LEVEL_TABLE[GetExpansionLevel()] then\n        aura_env.var[\"kill_count\"] = aura_env.var[\"kill_count\"] + 1\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" and UnitLevel(\"player\") == MAX_PLAYER_LEVEL_TABLE[GetExpansionLevel()] then\n        if arg2 == \"UNIT_DIED\" then  -- CLEU函数里arg2参数2表示子事件类型\n            --print(CombatLogGetCurrentEventInfo())\n            if type(string.find(aura_env.config[\"exclude_monster\"], arg9)) == \"nil\" then\n                aura_env.var[\"kill_count\"] = aura_env.var[\"kill_count\"] + 1\n                if aura_env.config[\"isdebug\"] then print(date(\"%H:%M:%S\") .. \" [DEBUG] \"..  arg9 .. \"死亡，杀怪数+1\") end\n            else\n                if aura_env.config[\"isdebug\"] then print(date(\"%H:%M:%S\") .. \" [DEBUG] \"..  arg9 .. \"在杀怪数排除怪物中\") end\n            end\n        end\n    elseif event == \"LOADING_SCREEN_DISABLED\" then\n        if not UnitIsDeadOrGhost(\"player\") then\n            aura_env.var[\"isUILoadingFinish\"] = 2\n        else\n            aura_env.var[\"end_time\"] = 0  -- 死亡loading会导致end_time被赋值，这里重置\n            if aura_env.config[\"isdebug\"] then print(date(\"%H:%M:%S\") .. \" [DEBUG] 死亡状态不重置isUILoadingFinish变量\") end\n        end\n    elseif event == \"UPDATE_INSTANCE_INFO\" then\n        if aura_env.var[\"isUILoadingFinish\"] == 2 then aura_env.var[\"isUILoadingFinish\"] = 1 end\n    end\nend",
