["customDuration"] = "function()\n    if not aura_env.tPackage then \n        return nil \n    else\n        return aura_env.tPackage.iDuration, aura_env.tPackage.iExpirationTime\n    end\nend\n\n\n",
["customName"] = "function()\n    if not aura_env.tPackage then \n        return nil \n    else \n        return aura_env.tPackage.sSpellName\n    end\nend",
["custom"] = "function(sEvent, ...)    \n    if sEvent == \"MultiDotFrame_CastStarted\" then\n        if select(1, ...) == aura_env.sFrameID then\n            aura_env.tPackage = select(2, ...)\n            \n            return true\n        end\n    elseif sEvent == \"MultiDotFrame_CastEnded\" then\n        if select(1, ...) == aura_env.sFrameID then\n            if aura_env.tPackage then\n                local tPackage = select(2, ...)\n                aura_env.tPackage.sSpellName = tPackage.sSpellName\n                aura_env.tPackage.iDuration = 0.5\n                aura_env.tPackage.iExpirationTime = GetTime() + 0.5\n                aura_env.tPackage.bEnded = true\n                return true\n            end\n        end\n    end\n    return false\nend\n\n\n",
