["init"] = {
["custom"] = "-- This WA is only used to localize some of the strings used in other WAs\naura_env.sLocale = \"enUS\"\naura_env.tLocalesTranslated = {\n    [\"frFR\"] = true,\n    [\"zhCN\"] = true,\n    [\"zhTW\"] = true,\n    [\"deDE\"] = true,\n    [\"ruRU\"] = true,\n    [\"koKR\"] = true,\n    [\"esES\"] = true,\n}\n\nlocal tLocData = {}\naura_env.tLocData = tLocData\ntLocData.tLocalizations = {\n    -- Testing\n    [\"The Great Forge\"] = nil,\n    [\"War Quarter\"] = nil,\n    [\"Valley of Honor\"] = nil,\n    [\"Heroic Training Dummy\"] = nil,\n    [\"Grandmaster's Training Dummy\"] = nil,\n    [\"Expert's Training Dummy\"] = nil,\n    -- Sartharion\n    [\"The Obsidian Sanctum\"] = nil,\n    [\"Tenebron\"] = nil,\n    [\"Shadron\"] = nil,\n    [\"Vesperon\"] = nil,\n    -- Naxx\n    [\"The Horsemen's Assembly\"] = nil,\n    [\"Baron Rivendare\"] = nil,\n    [\"Thane Korth'azz\"] = nil,\n    [\"Lady Blaumeux\"] = nil,\n    -- Ulduar\n    [\"Formation Grounds\"] = nil,\n    [\"Flame Leviathan\"] = nil,\n    [\"The Colossal Forge\"] = nil,\n    [\"Ignis the Furnace Master\"] = nil,\n    [\"Razorscale's Aerie\"] = nil,\n    [\"Razorscale\"] = nil,\n    [\"The Scrapyard\"] = nil,\n    [\"XT-002 Deconstructor\"] = nil,\n    [\"The Celestial Planetarium\"] = nil,\n    [\"Algalon the Observer\"] = nil,\n    [\"The Observation Ring\"] = nil,\n    [\"Auriaya\"] = nil,\n    [\"The Halls of Winter\"] = nil,\n    [\"Hodir\"] = nil,\n    [\"The Clash of Thunder\"] = nil,\n    [\"Thorim\"] = nil,\n    [\"The Descent into Madness\"] = nil,\n    [\"General Vezax\"] = nil,\n    [\"The Prison of Yogg-Saron\"] = nil,\n    [\"Yogg-Saron\"] = nil,\n    [\"The Assembly of Iron\"] = nil,\n    [\"Stormcaller Brundir\"] = nil,\n    [\"Runemaster Molgeim\"] = nil,\n    [\"Steelbreaker\"] = nil,\n    [\"The Shattered Walkway\"] = nil,\n    [\"Right Arm\"] = nil,\n    [\"Kologarn\"] = nil,\n    [\"Left Arm\"] = nil,\n    [\"The Conservatory of Life\"] = nil,\n    [\"Snaplasher\"] = nil,\n    [\"Storm Lasher\"] = nil,\n    [\"Ancient Water Spirit\"] = nil,\n    [\"The Spark of Imagination\"] = nil,\n    [\"Aerial Command Unit\"] = nil,\n    [\"VX-001\"] = nil,\n    [\"Leviathan Mk II\"] = nil,\n    [\"Saronite Animus\"] = nil,\n    [\"Life Spark\"] = nil,\n    [\"XM-024 Pummeller\"] = nil,\n    [\"Freya\"] = nil,\n    [\"Assault Bot\"] = nil,\n    [\"Crusher Tentacle\"] = nil,\n    [\"Corruptor Tentacle\"] = nil,\n    -- TOC\n    [\"Trial of the Crusader\"] = nil,\n    [\"Gormok the Impaler\"] = nil,\n    [\"Snobold Vassal\"] = nil,\n    [\"Acidmaw\"] = nil,\n    [\"Dreadscale\"] = nil,\n    [\"Icehowl\"] = nil,\n    [\"Lord Jaraxxus\"] = nil,\n    [\"Nether Portal\"] = nil,\n    [\"Infernal Volcano\"] = nil,\n    [\"Mistress of Pain\"] = nil,\n    [\"Shaabad\"] = nil,\n    [\"Broln Stouthorn\"] = nil,\n    [\"Anthar Forgemender\"] = nil,\n    [\"Caiphus the Stern\"] = nil,\n    [\"Melador Valestrider\"] = nil,\n    [\"Erin Misthoof\"] = nil,    \n    [\"Saamul\"] = nil,\n    [\"Thrakgar\"] = nil,\n    [\"Irieth Shadowstep\"] = nil,\n    [\"Maz'dinah\"] = nil,\n    [\"Shocuul\"] = nil,\n    [\"Narrhok Steelbreaker\"] = nil, \n    [\"Alyssia Moonstalker\"] = nil,\n    [\"Ruj'kah\"] = nil,\n    [\"Tyrius Duskblade\"] = nil,\n    [\"Gorgrim Shadowcleave\"] = nil,\n    [\"Serissa Grimdabbler\"] = nil,\n    [\"Harkzog\"] = nil, \n    [\"Baelnor Lightbearer\"] = nil,\n    [\"Malithas Brightblade\"] = nil,\n    [\"Velanaa\"] = nil,\n    [\"Liandra Suncaller\"] = nil,\n    [\"Kavina Grovesong\"] = nil,\n    [\"Birana Stormhoof\"] = nil, \n    [\"Brienna Nightfell\"] = nil,\n    [\"Vivienne Blackwhisper\"] = nil,\n    [\"Noozle Whizzlestick\"] = nil,\n    [\"Ginselle Blightslinger\"] = nil,\n    [\"Fjola Lightbane\"] = nil,\n    [\"Eydis Darkbane\"] = nil,\n    [\"The Icy Depths\"] = nil,\n    [\"Anub'arak\"] = nil,\n    [\"Nerubian Burrower\"] = nil,\n    [\"Onyxia's Lair\"] = nil,\n    [\"Onyxia\"] = nil,\n    [\"Onyxian Lair Guard\"] = nil,\n    -- ICC\n    [\"The Spire\"] = nil,\n    [\"Lord Marrowgar\"] = nil,\n    [\"Bone Spike\"] = nil,\n    [\"Oratory of the Damned\"] = nil,\n    [\"Lady Deathwhisper\"] = nil,\n    [\"Cult Adherent\"] = nil,\n    [\"Cult Fanatic\"] = nil,\n    [\"Rampart of Skulls\"] = nil,\n    [\"Muradin Bronzebeard\"] = nil,\n    [\"High Overlord Saurfang\"] = nil,\n    [\"Deathbringer's Rise\"] = nil,\n    [\"Deathbringer Saurfang\"] = nil,\n    [\"Blood Beast\"] = nil,\n    [\"The Plagueworks\"] = nil,\n    [\"Festergut\"] = nil,\n    [\"Rotface\"] = nil,\n    [\"Little Ooze\"] = nil,\n    [\"Putricide's Laboratory of Alchemical Horrors and Fun\"] = nil,\n    [\"Volatile Ooze\"] = nil,\n    [\"Professor Putricide\"] = nil,\n    [\"Gas Cloud\"] = nil,\n    [\"The Crimson Hall\"] = nil,\n    [\"Prince Taldaram\"] = nil,\n    [\"Prince Keleseth\"] = nil,\n    [\"Prince Valanar\"] = nil,\n    [\"The Sanctum of Blood\"] = nil,\n    [\"Blood-Queen Lana'thel\"] = nil,\n    [\"The Frostwing Halls\"] = nil,\n    [\"Valithria Dreamwalker\"] = nil,\n    [\"Gluttonous Abomination\"] = nil,\n    [\"Risen Archmage\"] = nil,\n    [\"Suppresser\"] = nil,\n    [\"The Frost Queen's Lair\"] = nil,\n    [\"Sindragosa\"] = nil,\n    [\"The Frozen Throne\"] = nil,\n    [\"The Lich King\"] = nil,\n    [\"Shambling Horror\"] = nil,\n    [\"Ice Sphere\"] = nil,\n    [\"Raging Spirit\"] = nil,\n    [\"Val'kyr Shadowguard\"] = nil,\n}\n\nlocal function LocalizeTable(tTableToLocalize)\n    if tTableToLocalize.bLocalized then return tTableToLocalize end\n    \n    local tLocalizedTable = {\n        bLocalized = GetLocale(),\n        \n    }\n    \n    local function LocalizeField(tIn, tOut, sKey)\n        local sLocalizedKey = sKey\n        if tLocData.tLocalizations[sKey] and tLocData.tLocalizations[sKey] then\n            sLocalizedKey = tLocData.tLocalizations[sKey]\n        end\n        \n        if type(tIn[sKey]) == \"table\" then\n            tOut[sLocalizedKey] = {}\n            \n            for k,_ in pairs(tIn[sKey]) do\n                LocalizeField(tIn[sKey], tOut[sLocalizedKey], k)\n            end\n        else\n            if tLocData.tLocalizations[tIn[sKey]] and tLocData.tLocalizations[tIn[sKey]] then\n                tOut[sLocalizedKey] = tLocData.tLocalizations[tIn[sKey]]\n            else\n                tOut[sLocalizedKey] = tIn[sKey]\n            end\n        end\n    end\n    \n    for k,_ in pairs(tTableToLocalize) do\n        LocalizeField(tTableToLocalize, tLocalizedTable, k)\n    end\n    \n    return tLocalizedTable\nend\ntLocData.fnLocalizeTable = LocalizeTable\n\nlocal function InitLoca()\n    --Uncomment for new locales\n    --if GetLocale() == aura_env.sLocale then \n    --WeakAuras.ScanEvents(\"MultiDotFrame_Localize\", tLocData)\n    --end\n    \n    if not aura_env.tLocalesTranslated[GetLocale()] then\n        WeakAuras.ScanEvents(\"MultiDotFrame_Localize\", tLocData)\n    end\nend\naura_env.fnInitLoca = InitLoca\n\nInitLoca()",
