["init"] = {
["custom"] = "-- Class Data DK Init\nlocal tAuraData = {}\naura_env.sPlayerClass = \"DEATHKNIGHT\"\n\ntAuraData.tDotOrderIndices = {\n    [1] = \"None\", \n    [2] = \"Frost Fever\", \n    [3] = \"Blood Plague\", \n}\n\ntAuraData.tDotAuras = {\n    -- DK\n    [55095] = \"Frost Fever\",\n    [55078] = \"Blood Plague\",\n}\n\ntAuraData.tCastTriggers = {\n    [50842] = \"Pestilence\",\n}\n\ntAuraData.tCastInfos = {\n    [\"Pestilence\"] = {\n        tRefreshAura = {\n            tRefreshGlyph = {\n                iGlyphID = 237635\n            },\n            tAuras = {\n                \"Frost Fever\",\n                \"Blood Plague\"\n            }\n        }\n    },\n}\n\ntAuraData.tSpellsInfos = {\n    [\"Frost Fever\"] = {\n        iDuration = 15,\n        sName = \"Frost Fever\",\n        iIcon = 237522,\n        iColorR = 0.254,\n        iColorG = 0.247,\n        iColorB = 9.247,\n        iTalentedDuration = {\n            iTalentPage = 3,\n            iTalentID = 5,\n            tIncDurations = {\n                [1] = 3,      \n                [2] = 6,      \n            },\n        },\n    },  \n    [\"Blood Plague\"] = {\n        iDuration = 15,\n        sName = \"Blood Plague\",\n        iIcon = 237514,\n        iColorR = 0.296,\n        iColorG = 0.947,\n        iColorB = 0.147,\n        iTalentedDuration = {\n            iTalentPage = 3,\n            iTalentID = 5,\n            tIncDurations = {\n                [1] = 3,      \n                [2] = 6,      \n            },\n        },\n    },  \n}\n\ntAuraData.tCastingModeBindings = aura_env.config.tCastingModeBindings.tDeathKnight\ntAuraData.tBlacklist = aura_env.config.tBlacklist\ntAuraData.tForceDoTOrder = aura_env.config.tForceDoTOrder.tDeathKnight\n\ntAuraData.fExecuteRange = 0.0\n\nlocal function SendAuraData()\n    WeakAuras.ScanEvents(\"MultiDotFrame_AuraData\", tAuraData, aura_env.sPlayerClass)\nend\n\naura_env.fnSendAuraData = SendAuraData\n\n",
