    [9829] = \"Shred\",\n    [9830] = \"Shred\",\n    [27001] = \"Shred\",\n    [27002] = \"Shred\",\n    [48571] = \"Shred\",\n    [48572] = \"Shred\",\n}\n\ntAuraData.tDamageInfos = {\n    [\"Starfire\"] = {\n        tIncreaseDurationAura = {\n            iDuration = 3,\n            iCount = 3,\n            iGlyphID = 237639,\n            tAuras = {\n                \"Moonfire\"\n            }\n        }\n    },\n    [\"Shred\"] = {\n        tIncreaseDurationAura = {\n            iDuration = 2,\n            iCount = 3,\n            iGlyphID = 237652,\n            tAuras = {\n                \"Rip\"\n            }\n        }\n    },\n}\n\ntAuraData.tSpellsInfos = {\n    [\"Insect Swarm\"] = {\n        iDuration = 12,\n        sName = \"Insect Swarm\",\n        iIcon = 136045,\n        iColorR = 0.154,\n        iColorG = 0.847,\n        iColorB = 0.031,\n        iTalentedDuration = {\n            iTalentPage = 1,\n            iTalentID = 28,\n            tIncDurations = {\n                [1] = 2,      \n            },\n        },\n    },  \n    [\"Moonfire\"] = {\n        iDuration = 12,\n        sName = \"Moonfire\",\n        iIcon = 136096,\n        iColorR = 0.121,\n        iColorG = 0.145,\n        iColorB = 0.931,\n        iTalentedDuration = {\n            iTalentPage = 1,\n            iTalentID = 28,\n            tIncDurations = {\n                [1] = 3,      \n            },\n        },\n    },  \n    [\"Faerie Fire\"] = {\n        iDuration = 300,\n        sName = \"Faerie Fire\",\n        iIcon = 136033,\n        iColorR = 0.948,\n        iColorG = 0.047,\n        iColorB = 0.934,\n    },  \n    [\"Mangle\"] = {\n        iDuration = 60,\n        sName = \"Mangle\",\n        iIcon = 132135,\n        iColorR = 1.000,\n        iColorG = 0.647,\n        iColorB = 0.031,\n    },  \n    [\"Rake\"] = {\n        iDuration = 9,\n        sName = \"Rake\",\n        iIcon = 132122,\n        iColorR = 1.000,\n        iColorG = 0.247,\n        iColorB = 0.247,\n    },  \n    [\"Rip\"] = {\n        iDuration = 12,\n        sName = \"Rip\",\n        iIcon = 132152,\n        iColorR = 0.796,\n        iColorG = 0.147,\n        iColorB = 0.147,\n        iSetBonusDuration = {\n            iItemCount = 2,\n            iIncDuration = 4,\n            tItems = {\n                39553,\n                39554,\n                39555,\n                39556,\n                39557,\n                40471,\n                40472,\n                40473,\n                40493,\n                40494\n            },\n        },\n    },  \n}\n\ntAuraData.tCastingModeBindings = aura_env.config.tCastingModeBindings.tDruid\ntAuraData.tBlacklist = aura_env.config.tBlacklist\ntAuraData.tForceDoTOrder = aura_env.config.tForceDoTOrder.tDruid\n\ntAuraData.fExecuteRange = 0\n\nlocal function SendAuraData()\n    WeakAuras.ScanEvents(\"MultiDotFrame_AuraData\", tAuraData, aura_env.sPlayerClass)\nend\n\naura_env.fnSendAuraData = SendAuraData\n\n",
