["custom"] = "if not aura_env.region._mouseoverFrame then\n    aura_env.region._mouseoverFrame = CreateFrame(\"FRAME\", nil, aura_env.region)\n    local frame = aura_env.region._mouseoverFrame\n    frame:SetAllPoints()\n    frame:SetScript(\"OnEnter\", function() WeakAuras.ScanEvents(\"_mouseoverFrame_event\", true) end)\n    frame:SetScript(\"OnLeave\", function() WeakAuras.ScanEvents(\"_mouseoverFrame_event\", false) end)\n    frame:SetMouseClickEnabled (false)\nend\n\n\naura_env.saved=aura_env.saved or {}\nfunction aura_env:loadevent(event,tb)    \n    if tb then\n        aura_env.saved[1]=tb or {}\n    end\nend\n\nfunction aura_env:getstr()\n    aura_env.saved[1]=aura_env.saved[1]  or {}\n    return  aura_env.saved[1].qitastr\nend\n\n\n\n\n\n\n",
["do_custom"] = true,
},
