},
["init"] = {
["custom"] = "aura_env.check = function(after)\n    if not after then \n        WeakAuras.ScanEvents(\"WA_NN_PETCOMBAT\")        \n        return\n    end\n    C_Timer.After(after,function()\n            WeakAuras.ScanEvents(\"WA_NN_PETCOMBAT\")\n    end)\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["custom_hide"] = "custom",
["type"] = "custom",
["names"] = {
},
["subeventSuffix"] = "_CAST_START",
["unit"] = "player",
["duration"] = "1",
["genericShowOn"] = "showOnActive",
["customOverlay1"] = "",
["unevent"] = "timed",
["custom"] = "function(event,...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        if string.sub(select(2,...),0,5) == \"SWING\" or string.sub(select(2,...),0,12) == \"SPELL_DAMAGE\" then\n            if UnitName(\"pet\") == select(5,...) then\n                aura_env.lastAttack = GetTime()\n                aura_env.check(4)\n                aura_env.check()                \n            end        \n        end\n    end\n    \n    --to not instantly show icon when we enter combat\n    if event == \"PLAYER_REGEN_DISABLED\" then\n        aura_env.lastAttack = GetTime()\n        aura_env.check(4)\n    end\n    \n    if event == \"WA_NN_PETCOMBAT\" then\n        if GetTime()-aura_env.lastAttack>3 then return true end\n    end\n    \n    \n    \n    \n    \nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["events"] = "COMBAT_LOG_EVENT_UNFILTERED PLAYER_REGEN_DISABLED WA_NN_PETCOMBAT",
["spellIds"] = {
},
