["init"] = {
["custom"] = "-- This WA is used to handle trigger logic of the HP Bars at a single location.\n\nlocal tBorderTrigger = {}\n\nlocal function PrintDebugLog(sText, fTimeToOffset)\n    if aura_env.tTriggerData.bDebug and aura_env.tTriggerData.bDebugBorderSharedTriggerPerf then\n        local sOffset = \"\"\n        local fTime = GetTime()\n        if fTimeToOffset ~= nil then\n            sOffset = \"(\" .. fTime - fTimeToOffset .. \")\"\n        end\n        print(sText, aura_env.sFrameID, fTime, sOffset)\n    end\nend\n\nlocal function HandleTrigger(sEvent, ...)\n    if aura_env.tTriggerData.iSkin ~= aura_env.iSkinID then return false end\n    if sEvent == \"PLAYER_TARGET_CHANGED\" then\n        local fTimeStart = GetTime()\n        PrintDebugLog(\"LClick - Start PLAYER_TARGET_CHANGED\")\n        aura_env.tData.fnSetIsTargeted()\n        PrintDebugLog(\"LClick - End PLAYER_TARGET_CHANGED\", fTimeStart)\n    elseif sEvent == \"MultiDotFrame_AttemptTarget\" then\n        local fTimeStart = GetTime()\n        PrintDebugLog(\"LClick - Start Attempt Target\")\n        if select(1, ...) == aura_env.sFrameID then\n            aura_env.tData.fnAttemptedToTarget()\n        end\n        PrintDebugLog(\"LClick - End Attempt Target\", fTimeStart)\n    elseif sEvent == \"MultiDotFrame_AttemptTarget_Cancel\" then\n        local fTimeStart = GetTime()\n        PrintDebugLog(\"LClick - Start Attempt Target Cancel\")\n        if select(1, ...) == aura_env.sFrameID then\n            aura_env.bFailedToTarget = 0   \n        end\n        PrintDebugLog(\"LClick - End Attempt Target Cancel\", fTimeStart)\n    elseif sEvent == \"MultiDotFrame_ChangeZone\" then \n        local tZoneData = select(2, ...)\n        if tZoneData == nil or tZoneData[aura_env.sFrameID] == nil then return false end\n        aura_env.sNPCID = tZoneData[aura_env.sFrameID].sNPCID\n        if aura_env.tData then\n            aura_env.tData.fnSetIsTargeted()\n        end\n    end\n    return true\nend\ntBorderTrigger.fnHandleTrigger = HandleTrigger \n\nlocal function Init()\n    tBorderTrigger.bDebug = aura_env.config.tDebug.bDebug\n    tBorderTrigger.bDebugBorderSharedTriggerPerf = aura_env.config.tDebug.bDebugBorderSharedTriggerPerf\n    tBorderTrigger.iSkin = aura_env.config.iSkin\n    WeakAuras.ScanEvents(\"MultiDotFrame_InitSharedTrigger_Borders\", tBorderTrigger)\nend\naura_env.fnInit = Init\n\n",
["do_custom"] = true,
},
