["customDuration"] = "function()\n    local target_guid = UnitGUID(\"target\")\n    local num_shreds = aura_env.shred_counts[target_guid] or 0\n    \n    return num_shreds == 3\nend",
["custom"] = "function(e, ...)\n    local timestamp, subevent, _, src_guid, src_name, _, _, dest_guid, dest_name, _, _, spell_id, spell_name = ...    \n    \n    if e == \"PLAYER_TARGET_CHANGED\" then\n        return true\n    end\n    \n    if src_guid == aura_env.player_guid and spell_id then\n        \n        local shred_counts = aura_env.shred_counts\n        \n        \n        if spell_id == 27002 or spell_id == 48571 or spell_id == 48572 then -- if shred (rank 7-9)\n            \n            local num_shreds = shred_counts[dest_guid] or 0\n            \n            if num_shreds < 3 then \n                \n                shred_counts[dest_guid] = num_shreds + 1\n                \n                return true\n            end\n            \n        elseif spell_id == 27008 or spell_id == 49799 or  spell_id == 49800 then -- if rip (rank 7-9)\n            \n            shred_counts[dest_guid] = 0\n            \n            return true\n        end\n    end\nend\n\n\n",
