["outline"] = "OUTLINE",
["wagoID"] = "5Pz4pCOF5",
["authorOptions"] = {
{
["type"] = "description",
["text"] = "|cFF6666FFJeyp's Boss Frames|r",
["fontSize"] = "medium",
["width"] = 2,
},
{
["type"] = "description",
["text"] = "|cFFFF6666Important |r: Always update your options when having the top most group of the WA selected (Jeyp's Boss Frames) to avoid desyncing the values.",
["fontSize"] = "medium",
["width"] = 2,
},
{
["type"] = "space",
["variableWidth"] = true,
["height"] = 1,
["width"] = 2,
["useHeight"] = false,
},
{
["desc"] = "|cFF6666FFClassic Skin|r : Progress bars showing the status of all DoTs in a visual way.|n|cFF66FF66Alternative Skin|r : Made by Solah. More compact and uses Icons to display the status of DoTs.",
["type"] = "select",
["values"] = {
"Classic",
"Alternative",
},
["default"] = 1,
["key"] = "iSkin",
["useDesc"] = true,
["name"] = "Skin",
["width"] = 2,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- [Shared Trigger DoTs] - This WA is used to handle trigger logic of the HP Bars at a single location.\nlocal tDotsTrigger = {}\n\nlocal function SetStateFixedProperties(allStates, tPackage)\n    allStates[tPackage.sSlotName].name = tPackage.name\n    allStates[tPackage.sSlotName].icon = tPackage.icon\n    allStates[tPackage.sSlotName].iOrder = tPackage.iOrder\n    allStates[tPackage.sSlotName].iColorR = tPackage.iColorR\n    allStates[tPackage.sSlotName].iColorG = tPackage.iColorG\n    allStates[tPackage.sSlotName].iColorB = tPackage.iColorB\n    allStates[tPackage.sSlotName].stacks = 1\n    allStates[tPackage.sSlotName].iIncreaseDurationCount = 0\nend\nlocal function AddState(allStates, tPackage)\n    if not allStates[tPackage.sSlotName] then\n        allStates[tPackage.sSlotName] = \n        {\n            show = true,\n            progressType = \"timed\",\n            autoHide = tPackage.autoHide,\n        }\n        SetStateFixedProperties(allStates, tPackage)\n    elseif allStates[tPackage.sSlotName].name ~= tPackage.name then -- Override current spell with another spell in same slot\n        SetStateFixedProperties(allStates, tPackage)\n    end\n    \n    allStates[tPackage.sSlotName].changed = true\n    allStates[tPackage.sSlotName].duration = tPackage.duration\n    allStates[tPackage.sSlotName].expirationTime = tPackage.expirationTime\n    \nend\nlocal function RemoveState(allStates, tPackage)\n    if allStates[tPackage.sSlotName] then\n        if allStates[tPackage.sSlotName].autoHide or tPackage.bForceClear then\n            allStates[tPackage.sSlotName] = \n            {\n                show = false,\n                changed = true,\n                stacks = 1,\n                iIncreaseDurationCount = 0,\n            } \n        else\n            allStates[tPackage.sSlotName].expirationTime = GetTime()\n            allStates[tPackage.sSlotName].stacks = 1\n            allStates[tPackage.sSlotName].iIncreaseDurationCount = 0\n            allStates[tPackage.sSlotName].changed = true\n        end\n        \n        return true\n    end\n    return false\nend\n\nlocal function RefreshState(allStates, tPackage)\n    if allStates[tPackage.sSlotName] and allStates[tPackage.sSpellName].expirationTime > GetTime() then \n        allStates[tPackage.sSlotName].changed = true\n        allStates[tPackage.sSlotName].duration = tPackage.duration\n        allStates[tPackage.sSlotName].expirationTime = tPackage.expirationTime\n        return true\n    end\n    return false\nend\n\nlocal function IncreaseDurationState(allStates, tPackage)\n    if allStates[tPackage.sSlotName] and allStates[tPackage.sSpellName].expirationTime > GetTime() then \n        if allStates[tPackage.sSlotName].iIncreaseDurationCount < tPackage.iCount then \n            allStates[tPackage.sSlotName].changed = true\n            allStates[tPackage.sSlotName].duration = allStates[tPackage.sSlotName].duration + tPackage.iDuration\n            allStates[tPackage.sSlotName].expirationTime = allStates[tPackage.sSlotName].expirationTime + tPackage.iDuration\n            allStates[tPackage.sSlotName].iIncreaseDurationCount = allStates[tPackage.sSlotName].iIncreaseDurationCount + 1\n            return true\n        end\n    end\n    return false\nend\n\nlocal function StackState(allStates, tPackage)\n    if allStates[tPackage.sSlotName] then \n        allStates[tPackage.sSlotName].changed = true\n        allStates[tPackage.sSlotName].stacks = tPackage.iStacks\n        return true\n    end\nend\n\nlocal function HandleTrigger(allStates, sEvent, ...)\n    if aura_env.tTriggerData.iSkin ~= aura_env.iSkinID then return false end\n    \n    if sEvent == \"MultiDotFrame_DoTUpdate\" then\n        local sSubEvent = select(1, ...)\n        local sFrame = select(2, ...)\n        local tPackage = select(3, ...)\n        \n        if sFrame ~= aura_env.sFrameID then return end\n        if sSubEvent == \"Add\" then\n            AddState(allStates, tPackage)            \n            return true\n        elseif sSubEvent == \"Remove\" then\n            return RemoveState(allStates, tPackage)   \n        elseif sSubEvent == \"Refresh\" then\n            return RefreshState(allStates, tPackage) \n        elseif sSubEvent == \"Stack\" then\n            return StackState(allStates, tPackage)\n        elseif sSubEvent == \"IncreaseDuration\" then\n            return IncreaseDurationState(allStates, tPackage)\n        end\n    elseif sEvent == \"MultiDotFrame_ChangeZone\" then\n        for k,_ in pairs(allStates) do \n            allStates[k] = {\n                show = false,\n                changed = true,\n            } \n        end\n        return true\n    end\n    return false\nend\ntDotsTrigger.fnHandleTrigger = HandleTrigger \n\nlocal function Init()\n    tDotsTrigger.iSkin = aura_env.config.iSkin\n    WeakAuras.ScanEvents(\"MultiDotFrame_InitSharedTrigger_DoTs\", tDotsTrigger)\nend\naura_env.fnInit = Init\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
