["custom"] = "local e = aura_env\nif not e.id then return end\nlocal region = WeakAuras.GetRegion(e.id)\nlocal VER = aura_env.config.SVer2\nif not region then return end\nif not _G[e.id..\"Button\"] then\n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region)\n    e.btn:SetAllPoints(region)\nend\n\nlocal btn = _G[e.id..\"Button\"]\nbtn:SetScript(\"OnEnter\", function(self)\n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n        GameTooltip:ClearLines()\n        GameTooltip:SetText(\"|cffffffffiTank WotLKC版本说明：|r\\n|cff919191数据模型：\\n防御技能540；\\命中8%，精准26；\\n数据显示部分缺少的数值显示的是等级数值。\\n盾牌格挡值2400之后收益衰减。\\n输出评分仅作输出能力参考。|r\")\nend)\n\nbtn:SetScript(\"OnLeave\", function(self)\n        GameTooltip:Hide()\nend)\n\nbtn:Show()",
},
