},
["preferToUpdate"] = true,
["customText"] = "function()\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "BOTTOM",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "function init()\n    local tplayerClass = string.upper(select(2, UnitClass('player')))\n    local NameFont = GameTooltipTextLeft1:GetFont()\n    local NumbFS = 16                -- 整体的数值描述的字大小\n    local NumbFSMain = NumbFS * 2    -- 攻强法伤显示数值的字大小\n    local NumbFSMain1 = NumbFS * 1.0 -- 攻强法伤描述的字大小\n    local NumbFSother = NumbFS * 1.2 -- 其他属性显示数值的字大小\n    local NumbFSother1 = NumbFS * 1.0 -- 其他显示描述的字大小\n    local FontF = \"THINOUTLINE\"\n    local PlayAs -- 1:物理DPS, 2:法术DPS, 3:治疗, 4:坦克, 5:猎人, 6:增强萨\n    local region = WeakAuras.GetRegion(aura_env.id)\n    local StatuFrame = CreateFrame(\"Frame\", \"StatuFrame\", region)\n    StatuFrame:SetWidth(100)\n    StatuFrame:SetHeight(75)\n    StatuFrame:SetAlpha(0.8)\n    StatuFrame:SetPoint(\"CENTER\", 0, 0)\n    StatuFrame:Show()\n    \n    -- 创建字体字符串\n    local statuMain = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statuMain:SetFont(NameFont, NumbFSMain, FontF)\n    statuMain:SetPoint('BOTTOMRIGHT', StatuFrame, 'BOTTOMLEFT', 0, 0)\n    statuMain:SetJustifyH('RIGHT')\n    local statu2 = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu2:SetFont(NameFont, NumbFSother, FontF)\n    statu2:SetPoint('TOPRIGHT', StatuFrame, 'BOTTOMLEFT', 0, 0)\n    statu2:SetJustifyH('RIGHT')\n    local statu3 = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu3:SetFont(NameFont, NumbFSother, FontF)\n    statu3:SetPoint('TOPRIGHT', StatuFrame, 'BOTTOMLEFT', 0, -NumbFSother)\n    statu3:SetJustifyH('RIGHT')\n    local statu4 = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu4:SetFont(NameFont, NumbFSother, FontF)\n    statu4:SetPoint('TOPRIGHT', StatuFrame, 'BOTTOMLEFT', 0, -NumbFSother*2)\n    statu4:SetJustifyH('RIGHT')\n    local statu5 = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu5:SetFont(NameFont, NumbFSother, FontF)\n    statu5:SetPoint('TOPRIGHT', StatuFrame, 'BOTTOMLEFT', 0, -NumbFSother*3)\n    statu5:SetJustifyH('RIGHT')\n    local statu6 = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu6:SetFont(NameFont, NumbFSother, FontF)\n    statu6:SetPoint('TOPRIGHT', StatuFrame, 'BOTTOMLEFT', 0, -NumbFSother*4)\n    statu6:SetJustifyH('RIGHT')\n    -- local statu7 = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    -- statu7:SetFont(NameFont, NumbFSother, FontF)\n    -- statu7:SetPoint('TOPRIGHT', StatuFrame, 'BOTTOMLEFT', 0, -NumbFSother*5)\n    -- statu7:SetJustifyH('RIGHT')\n    -- 描述文字\n    local statuMainDes = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statuMainDes:SetFont(NameFont, NumbFSMain1, FontF)\n    statuMainDes:SetPoint('BOTTOMLEFT', statuMain, 'BOTTOMRIGHT', 5, 5)\n    statuMainDes:SetJustifyH('LEFT')\n    local statu2Des = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu2Des:SetFont(NameFont, NumbFSother1, FontF)\n    statu2Des:SetPoint('BOTTOMLEFT', statu2, 'BOTTOMRIGHT', 5, 2)\n    statu2Des:SetJustifyH('LEFT')\n    local statu3Des = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu3Des:SetFont(NameFont, NumbFSother1, FontF)\n    statu3Des:SetPoint('BOTTOMLEFT', statu3, 'BOTTOMRIGHT', 5, 2)\n    statu3Des:SetJustifyH('LEFT')\n    local statu4Des = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu4Des:SetFont(NameFont, NumbFSother1, FontF)\n    statu4Des:SetPoint('BOTTOMLEFT', statu4, 'BOTTOMRIGHT', 5, 2)\n    statu4Des:SetJustifyH('LEFT')\n    local statu5Des = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu5Des:SetFont(NameFont, NumbFSother1, FontF)\n    statu5Des:SetPoint('BOTTOMLEFT', statu5, 'BOTTOMRIGHT', 5, 2)\n    statu5Des:SetJustifyH('LEFT')\n    local statu6Des = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    statu6Des:SetFont(NameFont, NumbFSother1, FontF)\n    statu6Des:SetPoint('BOTTOMLEFT', statu6, 'BOTTOMRIGHT', 5, 2)\n    statu6Des:SetJustifyH('LEFT')\n    -- local statu7Des = StatuFrame:CreateFontString(nil, 'OVERLAY')\n    -- statu7Des:SetFont(NameFont, NumbFSother1, FontF)\n    -- statu7Des:SetPoint('BOTTOMLEFT', statu7, 'BOTTOMRIGHT', 5, 2)\n    -- statu7Des:SetJustifyH('LEFT')\n    \n    -- 检查 Buff 的辅助函数\n    local function HasBuff(spellID)\n        local i = 1\n        while true do\n            local name, _, _, _, _, _, _, _, _, id = UnitBuff(\"player\", i)\n            if not name then break end\n            if id == spellID then return true end\n            i = i + 1\n        end\n        return false\n    end\n    \n    local function GetCurrentInfo()\n        local tplayerClass = string.upper(select(2, UnitClass(\"player\")))\n        local num1, num2, num3 = 0, 0, 0\n        for i = 1, GetNumTalents(1) do\n            local _, _, _, _, points = GetTalentInfo(1, i)\n            num1 = num1 + (points or 0)\n        end\n        for i = 1, GetNumTalents(2) do\n            local _, _, _, _, points = GetTalentInfo(2, i)\n            num2 = num2 + (points or 0)\n        end\n        for i = 1, GetNumTalents(3) do\n            local _, _, _, _, points = GetTalentInfo(3, i)\n            num3 = num3 + (points or 0)\n        end\n        \n        local usetalent\n        if num1 > num2 and num1 > num3 then\n            usetalent = 1 -- 神圣\n        elseif num2 > num1 and num2 > num3 then\n            usetalent = 2 -- 防护\n        elseif num3 > num1 and num3 > num2 then\n            usetalent = 3 -- 惩戒\n        else\n            usetalent = 3 -- 默认惩戒（点数相等时）\n        end\n        \n        PlayAs = 1 -- 默认设置为物理 DPS\n        \n        if tplayerClass == \"DEATHKNIGHT\" then\n            if HasBuff(48263) then -- 冰霜灵气（坦克）\n                PlayAs = 4\n            else\n                PlayAs = 1\n            end\n        elseif tplayerClass == \"DRUID\" then\n            if usetalent == 1 then -- 平衡\n                PlayAs = 2\n            elseif usetalent == 2 and GetShapeshiftFormID() == 8 then -- 熊形态\n                PlayAs = 4\n            elseif usetalent == 3 then -- 恢复\n                PlayAs = 3\n            else\n                PlayAs = 1 -- 野性（猫）\n            end\n        elseif tplayerClass == \"PALADIN\" then\n            if usetalent == 1 then -- 神圣\n                PlayAs = 3\n            elseif usetalent == 2 then -- 防护\n                PlayAs = 4\n            elseif usetalent == 3 then -- 惩戒\n                PlayAs = 1\n            end\n        elseif tplayerClass == \"SHAMAN\" then\n            if usetalent == 1 then -- 元素\n                PlayAs = 2\n            elseif usetalent == 2 then -- 增强\n                PlayAs = 6\n            else -- 恢复\n                PlayAs = 3\n            end\n        elseif tplayerClass == \"PRIEST\" then\n            if usetalent == 3 then -- 暗影\n                PlayAs = 2\n            else -- 戒律或神圣\n                PlayAs = 3\n            end\n        elseif tplayerClass == \"WARRIOR\" then\n            if GetShapeshiftFormID() == 18 then -- 防御姿态\n                PlayAs = 4\n            else\n                PlayAs = 1\n            end\n        elseif tplayerClass == \"ROGUE\" then\n            PlayAs = 1\n        elseif tplayerClass == \"HUNTER\" then\n            PlayAs = 5\n        elseif tplayerClass == \"MAGE\" then\n            PlayAs = 2\n        elseif tplayerClass == \"WARLOCK\" then\n            PlayAs = 2\n        end\n    end\n    \n    local function updateStatu(playas)\n        -- local MSpercent = math.floor(GetUnitSpeed(\"player\") / 7 * 100 + 0.5)\n        -- if MSpercent == 0 then\n        --     statu7:SetText(\"|cff00ffff0\")\n        -- else\n        --     statu7:SetText(\"|cff00ffff\" .. MSpercent)\n        -- end\n        -- statu7Des:SetText(\"移速\")\n        \n        if playas == 1 then -- 物理 DPS\n            local base, posBuff, negBuff = UnitAttackPower(\"player\")\n            local effective = base + posBuff + negBuff\n            statuMain:SetText(\"|cffff3333\" .. effective)\n            statuMainDes:SetText(\"攻强\")\n            statu2:SetText(format(\"|cffffffcc%.2f%%\", GetCombatRatingBonus(CR_HASTE_MELEE) or 0))\n            statu2Des:SetText(\"急速\")\n            statu3:SetText(format(\"|cffffffcc%.2f%%\", GetCritChance()))\n            statu3Des:SetText(\"暴击\")\n            local crb = GetCombatRatingBonus(CR_HIT_MELEE) or 0\n            local hm = GetHitModifier() or 0\n            statu4:SetText(format(\"|cffffffcc%.2f%%\", hm + crb))\n            statu4Des:SetText(\"命中\")\n            statu5:SetText(format(\"|cffffffcc%.2f%%\", GetArmorPenetration() or 0))\n            statu5Des:SetText(\"破甲\")\n            local mainSpeed, offSpeed = UnitAttackSpeed(\"player\")\n            if offSpeed then\n                statu6:SetText(format(\"|cffffff66%.2f/%.2f\", mainSpeed, offSpeed))\n            else\n                statu6:SetText(format(\"|cffffff66%.2f\", mainSpeed))\n            end\n            statu6Des:SetText(\"攻速\")\n        elseif playas == 2 then -- 法术 DPS\n            local SpellDamage = math.max(GetSpellBonusDamage(3), GetSpellBonusDamage(4), GetSpellBonusDamage(5), GetSpellBonusDamage(6), GetSpellBonusDamage(7))\n            statuMain:SetText(\"|cffff3333\" .. SpellDamage)\n            statuMainDes:SetText(\"法伤\")\n            statu2:SetText(format(\"|cffffff66%.2f%%\", GetCombatRatingBonus(CR_HASTE_SPELL) or 0))\n            statu2Des:SetText(\"急速\")\n            statu3:SetText(format(\"|cffffff66%.2f%%\", GetSpellCritChance(7) or 0))\n            statu3Des:SetText(\"暴击\")\n            local spellHit = GetCombatRatingBonus(CR_HIT_SPELL) or 0\n            statu4:SetText(format(\"|cffffff66%.2f%%\", spellHit))\n            statu4Des:SetText(\"命中\")\n            local base, casting = GetManaRegen()\n            statu5:SetText(format(\"|cff0066cc%d/%d\", base * 5, casting * 5))\n            statu5Des:SetText(\"法回\")\n            statu6:SetText(format(\"|cffffff33%d\", UnitHealthMax(\"player\")))\n            statu6Des:SetText(\"血量\")\n        elseif playas == 3 then -- 治疗\n            statuMain:SetText(\"|cff00ff00\" .. GetSpellBonusHealing())\n            statuMainDes:SetText(\"法强\")\n            statu2:SetText(format(\"|cffffff33%.2f%%\", GetCombatRatingBonus(CR_HASTE_SPELL) or 0))\n            statu2Des:SetText(\"急速\")\n            statu3:SetText(format(\"|cffffffcc%.2f%%\", GetSpellCritChance(2) or 0))\n            statu3Des:SetText(\"暴击\")\n            local spellHit = GetCombatRatingBonus(CR_HIT_SPELL) or 0\n            statu4:SetText(format(\"|cffffff66%.2f%%\", spellHit))\n            statu4Des:SetText(\"命中\")\n            local base, casting = GetManaRegen()\n            statu5:SetText(format(\"|cff0066cc%d/%d\", base * 5, casting * 5))\n            statu5Des:SetText(\"法回\")\n            statu6:SetText(format(\"|cffffff33%d\", UnitPowerMax(\"player\")))\n            statu6Des:SetText(\"蓝量\")\n        elseif playas == 4 then -- 坦克\n            local baseArmor, effectiveArmor = UnitArmor(\"player\")\n            statuMain:SetText(\"|cff0066cc\" .. effectiveArmor)\n            statuMainDes:SetText(\"护甲\")\n            statu2:SetText(format(\"|cffffffcc%.2f%%\", GetDodgeChance()))\n            statu2Des:SetText(\"躲闪\")\n            statu3:SetText(format(\"|cffcc99cc%.2f%%\", GetParryChance()))\n            statu3Des:SetText(\"招架\")\n            statu4:SetText(format(\"|cffffff33%.2f%%\", GetBlockChance()))\n            statu4Des:SetText(\"格挡\")\n            local crb = GetCombatRatingBonus(CR_HIT_MELEE) or 0\n            local hm = GetHitModifier() or 0\n            statu5:SetText(format(\"|cffffffcc%.2f%%\", crb + hm))\n            statu5Des:SetText(\"命中\")\n            statu6:SetText(format(\"|cffffff33%d\", UnitHealthMax(\"player\")))\n            statu6Des:SetText(\"血量\")\n        elseif playas == 5 then -- 猎人\n            local base, posBuff, negBuff = UnitRangedAttackPower(\"player\")\n            local effective = base + posBuff + negBuff\n            statuMain:SetText(\"|cffff3333\" .. effective)\n            statuMainDes:SetText(\"攻强\")\n            statu2:SetText(format(\"|cffffffcc%.2f%%\", GetCombatRatingBonus(CR_HASTE_RANGED) or 0))\n            statu2Des:SetText(\"急速\")\n            statu3:SetText(format(\"|cffffffcc%.2f%%\", GetRangedCritChance()))\n            statu3Des:SetText(\"暴击\")\n            local crbr = GetCombatRatingBonus(CR_HIT_RANGED) or 0\n            local hmr = GetHitModifier() or 0\n            statu4:SetText(format(\"|cffffffcc%.2f%%\", crbr + hmr))\n            statu4Des:SetText(\"命中\")\n            statu5:SetText(format(\"|cffffffcc%.2f%%\", GetArmorPenetration() or 0))\n            statu5Des:SetText(\"破甲\")\n            local speed = UnitRangedDamage(\"player\")\n            statu6:SetText(format(\"|cffffff66%.2f\", speed))\n            statu6Des:SetText(\"攻速\")\n        elseif playas == 6 then -- 增强萨\n            local base, posBuff, negBuff = UnitAttackPower(\"player\")\n            local effective = base + posBuff + negBuff\n            local SpellDamage = math.max(GetSpellBonusDamage(3), GetSpellBonusDamage(4), GetSpellBonusDamage(5), GetSpellBonusDamage(6), GetSpellBonusDamage(7))\n            statuMain:SetText(\"|cffff3333\" .. effective .. \"/\" .. SpellDamage)\n            statuMainDes:SetText(\"攻法\")\n            statu2:SetText(format(\"|cffffffcc%.2f%%\", GetCombatRatingBonus(CR_HASTE_MELEE) or 0))\n            statu2Des:SetText(\"急速\")\n            statu3:SetText(format(\"|cffffffcc%.2f%%\", GetCritChance()))\n            statu3Des:SetText(\"暴击\")\n            local spellHit = GetCombatRatingBonus(CR_HIT_SPELL) or 0\n            statu4:SetText(format(\"|cffffff66%.2f%%\", spellHit))\n            statu4Des:SetText(\"命中\")\n            statu5:SetText(format(\"|cffffffcc%.2f%%\", GetArmorPenetration() or 0))\n            statu5Des:SetText(\"破甲\")\n            local mainSpeed, offSpeed = UnitAttackSpeed(\"player\")\n            if offSpeed then\n                statu6:SetText(format(\"|cffffff66%.2f/%.2f\", mainSpeed, offSpeed))\n            else\n                statu6:SetText(format(\"|cffffff66%.2f\", mainSpeed))\n            end\n            statu6Des:SetText(\"攻速\")\n        end\n    end\n    \n    StatuFrame:RegisterEvent(\"ACTIVE_TALENT_GROUP_CHANGED\")\n    StatuFrame:RegisterEvent(\"PLAYER_TALENT_UPDATE\")\n    StatuFrame:RegisterEvent(\"UPDATE_SHAPESHIFT_FORM\")\n    StatuFrame:RegisterEvent(\"PLAYER_REGEN_DISABLED\")\n    StatuFrame:RegisterEvent(\"PLAYER_REGEN_ENABLED\")\n    StatuFrame:RegisterEvent(\"ADDON_LOADED\")\n    StatuFrame:RegisterEvent(\"UNIT_AURA\")\n    StatuFrame:SetScript(\"OnEvent\", function(self, event)\n            if event == \"UNIT_AURA\" or event == \"UPDATE_SHAPESHIFT_FORM\" or event == \"ACTIVE_TALENT_GROUP_CHANGED\" or event == \"PLAYER_TALENT_UPDATE\" then\n                GetCurrentInfo()\n                updateStatu(PlayAs)\n            elseif event == \"PLAYER_REGEN_DISABLED\" then\n                StatuFrame:SetAlpha(0.9)\n            elseif event == \"PLAYER_REGEN_ENABLED\" then\n                StatuFrame:SetAlpha(0.5)\n            end\n    end)\n    \n    local TimeSinceLastUpdate = 0\n    local f = CreateFrame(\"Frame\", nil, UIParent)\n    f:SetScript(\"OnUpdate\", function(self, elapsed)\n            TimeSinceLastUpdate = TimeSinceLastUpdate + elapsed\n            if TimeSinceLastUpdate > 0.5 then\n                updateStatu(PlayAs or 1)\n                TimeSinceLastUpdate = 0\n            end\n    end)\n    \n    StatuFrame:SetPoint(\"CENTER\")\n    region:SetScript(\"OnSizeChanged\", StatuFrame.OnSizeChanged)\n    StatuFrame:Show()\n    GetCurrentInfo() -- 初始化时调用一次\nend\ninit()",
["do_custom"] = true,
},
},
