},
["custom"] = "function()\n    local classid = select(3, UnitClass(\"player\"))\n    local tp1 = select(5, GetTalentTabInfo(1))\n    local tp2 = select(5, GetTalentTabInfo(2))\n    local tp3 = select(5, GetTalentTabInfo(3))\n    \n    if classid == 1 then\n        if tp3 > 10 then\n            aura_env.role(\"TANK\")\n        else\n            aura_env.role(\"MELEE\")\n        end\n        \n    elseif classid == 2 then\n        if tp1 > 21 then\n            aura_env.role(\"HEALER\")\n        elseif tp2 > 20 then\n            aura_env.role(\"TANK\")\n        else\n            aura_env.role(\"MELEE\")\n        end\n        \n    elseif classid == 3 then\n        aura_env.role(\"RANGE\")\n        \n    elseif classid == 4 then\n        aura_env.role(\"MELEE\")\n        \n    elseif classid == 5 then\n        if tp1 > 20 or tp2 > 20 then\n            aura_env.role(\"HEALER\")\n        else\n            aura_env.role(\"RANGE\")\n        end\n        \n    elseif classid == 6 then\n        if select(5, GetTalentInfo(1, 21)) > 0 then\n            aura_env.role(\"TANK\")\n        else\n            aura_env.role(\"MELEE\")\n        end\n        \n    elseif classid == 7 then\n        if tp3 > 0 then\n            aura_env.role(\"HEALER\")\n        elseif tp1 > 20 then\n            aura_env.role(\"RANGE\")\n        else\n            aura_env.role(\"MELEE\")\n        end\n        \n    elseif classid == 8 then\n        aura_env.role(\"RANGE\")\n        \n    elseif classid == 9 then\n        aura_env.role(\"RANGE\")\n        \n    elseif classid == 11 then\n        if tp3 > 20 then\n            aura_env.role(\"HEALER\")\n        elseif tp1 > 20 then\n            aura_env.role(\"RANGE\")\n        elseif select(5, GetTalentInfo(2, 1)) > 0 or select(5, GetTalentInfo(2, 28)) > 0 or select(5, GetTalentInfo(2, 29)) > 0 then\n            aura_env.role(\"TANK\")\n        else\n            aura_env.role(\"MELEE\")\n        end\n    end\nend",
