["MDF - DoT Dispatcher"] = {
["outline"] = "OUTLINE",
["wagoID"] = "5Pz4pCOF5",
["authorOptions"] = {
{
["type"] = "description",
["text"] = "|cFF6666FFJeyp's Boss Frames|r",
["fontSize"] = "medium",
["width"] = 2,
},
{
["type"] = "description",
["text"] = "|cFFFF6666Important |r: Always update your options when having the top most group of the WA selected (Jeyp's Boss Frames) to avoid desyncing the values.",
["fontSize"] = "medium",
["width"] = 2,
},
{
["type"] = "space",
["variableWidth"] = true,
["height"] = 1,
["width"] = 2,
["useHeight"] = false,
},
{
["type"] = "toggle",
["default"] = true,
["desc"] = "Whether or not to show grayed out display when a DoT has been applied to an unit but has since expired.",
["key"] = "bShowMissingDoTs",
["useDesc"] = true,
["name"] = "Show Missing DoTs",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- DOT Dispatcher Init\naura_env.tAuraData = nil\naura_env.sPlayerGUID = UnitGUID(\"player\")\naura_env.sPlayerClass = select(2, UnitClass(\"player\"))\naura_env.bActive = false\naura_env.bHasRefreshedTalents = false\n\nlocal tFrameList = {\"A\",\"B\",\"C\",\"D\"}\n\naura_env.tNPCIdToFrames = {\n    \n}\n\naura_env.tFrameToNPCIds = {\n    \n}\n\nlocal function GetSpellInfos(sSpellName)\n    return aura_env.tAuraData.tSpellsInfos[sSpellName]\nend\n\nlocal function HandleSpellCLEU(sSpellID, sFrame, ...)\n    local sSpellName = aura_env.tAuraData.tDotAuras[sSpellID]\n    local sSubEvent = select(2, ...)\n    \n    if sSubEvent == \"SPELL_AURA_APPLIED\" or sSubEvent == \"SPELL_AURA_REFRESH\" then \n        aura_env.fnAddDebuff(sFrame, sSpellName)\n    elseif sSubEvent == \"SPELL_AURA_APPLIED_DOSE\" then\n        local iStack = select(16, ...)\n        aura_env.fnAddStack(sFrame, sSpellName, iStack)\n    elseif sSubEvent == \"SPELL_DAMAGE\" or sSubEvent == \"SPELL_ABSORBED\" then \n        if aura_env.tAuraData.tDamageTriggers[sSpellID] then \n            aura_env.fnDamageTrigger(aura_env.tAuraData.tDamageTriggers[sSpellID], sFrame)\n        end\n    elseif sSubEvent == \"SPELL_CAST_SUCCESS\" then\n        if aura_env.tAuraData.tCastTriggers[sSpellID] then \n            aura_env.fnCastTrigger(aura_env.tAuraData.tCastTriggers[sSpellID], sFrame)\n        end\n    elseif sSubEvent == \"SPELL_AURA_REMOVED\" then \n        aura_env.fnRemoveDebuff(sFrame, sSpellName)\n    end \nend\n\nlocal function HandleCLEU(...)\n    if not aura_env.bActive or aura_env.tAuraData == nil then return false end\n    \n    local sSourceGUID = select(4, ...)\n    local sTargetGUID = select(8, ...)\n    local sTargetNPCID = select(6, strsplit(\"-\", sTargetGUID))\n    \n    if sSourceGUID == aura_env.sPlayerGUID and aura_env.tNPCIdToFrames[sTargetNPCID] then \n        local sFrame = aura_env.tNPCIdToFrames[sTargetNPCID]\n        local sSpellID = select(12, ...)\n        \n        if not aura_env.bHasRefreshedTalents then\n            if aura_env.tAuraData then\n                aura_env.tAuraData.fnCheckTalentsAndGlyphs()\n            end    \n        end\n        \n        if sSpellID then \n            HandleSpellCLEU(sSpellID, sFrame, ...)\n        end\n    end\nend\naura_env.fnHandleCLEU = HandleCLEU\n\n-- Stored NPCID<->Frame correspondance in tables for quick access\nlocal function SetNPCIDToFrame(sFrame, tSharedZoneData)\n    if tSharedZoneData == nil then return false end\n    local tZoneData = tSharedZoneData[sFrame]\n    if tZoneData == nil or tZoneData.sNPCID == nil then return false end\n    \n    if aura_env.tFrameToNPCIds[sFrame] ~= nil then\n        aura_env.tNPCIdToFrames[aura_env.tFrameToNPCIds[sFrame]] = nil\n    end\n    \n    aura_env.tFrameToNPCIds[sFrame] = tZoneData.sNPCID\n    aura_env.tNPCIdToFrames[tZoneData.sNPCID] = sFrame\nend\n\n-- Register the NPC ID with each frame for easier lookup later\nlocal function SetNPCIDToFrames(sEvent, tZoneData) \n    local bRetVal = false\n    for _,sFrame in ipairs(tFrameList) do\n        bRetVal = bRetVal or SetNPCIDToFrame(sFrame, tZoneData)\n    end\n    \n    return bRetVal\nend\naura_env.fnSetNPCIDToFrames = SetNPCIDToFrames\n\n-- Evaluate whether the DoT is affected by haste and if yes rescale its normal duration with the level of haste of the player\nlocal function GetDoTDuration(sSpellName)\n    if not GetSpellInfos(sSpellName).bAffectedByHaste then \n        return GetSpellInfos(sSpellName).iFinalDuration or 0\n    else\n        -- 12458 is the spell ID of a 5-minute (or 300000ms) cast time.\n        -- Longer cast => more significant digits => more accurate haste estimation\n        local fHastePct = 300000/(select(4,GetSpellInfo(12458)))\n        \n        return GetSpellInfos(sSpellName).iFinalDuration / fHastePct\n    end\nend\n\n-- Called when an aura is refresh by an effect such as Everlasting affliction\nlocal function AttemptToRefreshSpell(sFrame, tAuras)\n    if not aura_env.bHasRefreshedTalents then return end\n    for _,sAura in pairs(tAuras) do\n        local sSpellName = sAura\n        local fTime = GetDoTDuration(sSpellName)\n        local tPackage = {\n            sSpellName = sSpellName,\n            sSlotName = GetSpellInfos(sSpellName).sSlotName,\n            duration = fTime,\n            expirationTime = GetTime() + fTime,\n        }\n        \n        WeakAuras.ScanEvents(\"MultiDotFrame_DoTUpdate\", \"Refresh\", sFrame, tPackage)\n    end\nend\naura_env.fnAttemptToRefreshSpell = AttemptToRefreshSpell\n\n-- Called when an aura duration is increased by an effect such as Glyph of Starfire\nlocal function AttemptToIncreaseDurationSpell(sFrame, tAuras, iDuration, iCount)\n    if not aura_env.bHasRefreshedTalents then return end\n    for _,sAura in pairs(tAuras) do\n        local sSpellName = sAura\n        local tPackage = {\n            sSpellName = sSpellName,\n            sSlotName = GetSpellInfos(sSpellName).sSlotName,\n            iDuration = iDuration,\n            iCount = iCount,\n        }\n        \n        WeakAuras.ScanEvents(\"MultiDotFrame_DoTUpdate\", \"IncreaseDuration\", sFrame, tPackage)\n    end\nend\naura_env.fnAttemptToIncreaseDurationSpell = AttemptToIncreaseDurationSpell\n\nlocal function ProcessSpellEvent(sFrame, tSpellInfos)\n    local fTime = GetTime()\n    if tSpellInfos and (tSpellInfos.fLastOcc or 0) + 0.1 < fTime then\n        if tSpellInfos.tRefreshAura and tSpellInfos.tRefreshAura.bEnabled then\n            aura_env.fnAttemptToRefreshSpell(sFrame, tSpellInfos.tRefreshAura.tAuras)\n        end\n        if tSpellInfos.tIncreaseDurationAura and tSpellInfos.tIncreaseDurationAura.bEnabled then\n            aura_env.fnAttemptToIncreaseDurationSpell(sFrame, tSpellInfos.tIncreaseDurationAura.tAuras, tSpellInfos.tIncreaseDurationAura.iDuration, tSpellInfos.tIncreaseDurationAura.iCount)\n        end\n        tSpellInfos.fLastOcc = fTime -- used to avoid double events of Starfire\n    end\nend\n\nlocal function DamageTrigger(sSpellName, sFrame)\n    local tDamageInfos = aura_env.tAuraData.tDamageInfos[sSpellName]\n    ProcessSpellEvent(sFrame, tDamageInfos)\nend\naura_env.fnDamageTrigger = DamageTrigger\n\nlocal function CastTrigger(sSpellName, sFrame)\n    local tCastInfos = aura_env.tAuraData.tCastInfos[sSpellName]\n    ProcessSpellEvent(sFrame, tCastInfos)\nend\naura_env.fnCastTrigger = CastTrigger\n\n-- Called for debuff that are exclusive to a single target such as Haunt\nlocal function RemoveDebuffFromOtherFrames(sFrame, sSpellName)\n    for _,sFrameID in ipairs(tFrameList) do\n        if sFrame ~= sFrameID then\n            aura_env.fnRemoveDebuff(sFrameID, sSpellName, true)\n        end\n    end\nend\n\n-- Called when a debuff is applied or refreshed manually\nlocal function AddDebuff(sFrame, sSpellName)\n    local tSpellInfo = GetSpellInfos(sSpellName)\n    if sSpellName == nil or tSpellInfo == nil then return end\n    if tSpellInfo.tRefreshAura and tSpellInfo.tRefreshAura.bEnabled then\n        aura_env.fnAttemptToRefreshSpell(sFrame, tSpellInfo.tRefreshAura.tAuras)\n    end\n    if tSpellInfo.sSlotName == nil or not tSpellInfo.bEnabled then return end\n    if tSpellInfo.bRemoveFromOtherFrames then\n        RemoveDebuffFromOtherFrames(sFrame, sSpellName)\n    end\n    \n    local fTime = GetDoTDuration(sSpellName)\n    local tPackage = {\n        sSpellName = sSpellName,\n        sSlotName = tSpellInfo.sSlotName,\n        duration = fTime,\n        expirationTime = GetTime() + fTime,\n        name = tSpellInfo.sName,\n        icon = tSpellInfo.iIcon,\n        iOrder = tSpellInfo.iOrder,\n        iColorR = tSpellInfo.iColorR,\n        iColorG = tSpellInfo.iColorG,\n        iColorB = tSpellInfo.iColorB,\n        autoHide = not aura_env.config.bShowMissingDoTs,\n    }\n    \n    WeakAuras.ScanEvents(\"MultiDotFrame_DoTUpdate\", \"Add\", sFrame, tPackage)\nend\naura_env.fnAddDebuff = AddDebuff \n\n-- Called when a stackable debuff gains a stack (as of writing this only used for Shadow Embrace stacks)\nlocal function AddStack(sFrame, sSpellName, iStacks)\n    if sSpellName == nil or GetSpellInfos(sSpellName) == nil then return end\n    local tPackage = {\n        sSpellName = sSpellName,\n        sSlotName = GetSpellInfos(sSpellName).sSlotName,\n        iStacks = iStacks,\n    }\n    \n    WeakAuras.ScanEvents(\"MultiDotFrame_DoTUpdate\", \"Stack\", sFrame, tPackage)\nend\naura_env.fnAddStack = AddStack \n\n-- Called when a debuff gets cleared off the target\nlocal function RemoveDebuff(sFrame, sSpellName, bForceClear)\n    if sSpellName == nil or GetSpellInfos(sSpellName) == nil then return end\n    local tPackage = {\n        sSpellName = sSpellName,\n        sSlotName = GetSpellInfos(sSpellName).sSlotName,\n        bForceClear = (bForceClear == true),\n    }\n    WeakAuras.ScanEvents(\"MultiDotFrame_DoTUpdate\", \"Remove\", sFrame, tPackage)\nend\naura_env.fnRemoveDebuff = RemoveDebuff\n\n",
["do_custom"] = true,
},
