["subeventPrefix"] = "SPELL",
["custom"] = "-- DOT Dispatcher Trigger\nfunction(sEvent, ...)\n    if sEvent == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        aura_env.fnHandleCLEU(...)\n    elseif sEvent == \"STATUS\" then\n        aura_env.bHasRefreshedTalents = false\n    elseif sEvent == \"ACTIVE_TALENT_GROUP_CHANGED\" then\n        if aura_env.tAuraData then\n            aura_env.tAuraData.fnCheckTalentsAndGlyphs()\n        end    \n    elseif sEvent == \"PLAYER_REGEN_DISABLED\" then\n        if not aura_env.bHasRefreshedTalents then\n            if aura_env.tAuraData then\n                aura_env.tAuraData.fnCheckTalentsAndGlyphs()\n            end    \n        end\n    elseif sEvent == \"MultiDotFrame_ClassData_Formatted\" then\n        aura_env.tAuraData = select(1, ...)\n    elseif sEvent == \"MultiDotFrame_ChangeZone\" then\n        local tZoneData = select(2, ...)\n        aura_env.bActive = tZoneData ~= nil\n        \n        aura_env.fnSetNPCIDToFrames(sEvent, tZoneData)\n    end \n    return true\nend\n\n\n\n",
