["disjunctive"] = "custom",
["customTriggerLogic"] = "function(t)\n    -- Author: 露露緹婭@Bilibili\n    -- 获取角色和职业信息\n    local role = UnitGroupRolesAssigned(\"player\")\n    local classId = select(3, UnitClass(\"player\"))\n    \n    -- 判断是否为特殊职责：治疗角色、圣骑士、团长、团长助理\n    local isSpecialRole = (role == \"HEALER\") or                    -- 治疗角色\n    UnitIsGroupLeader(\"player\") or            -- 团长\n    UnitIsGroupAssistant(\"player\")          -- 团长助理\n    --classId == 2                              -- 圣骑士\n    \n    -- 调试输出（可选，测试时启用）\n    --print(\"Role:\", role, \"ClassId:\", classId, \"Special:\", isSpecialRole)\n    \n    return t[1] and isSpecialRole\nend",
["activeTriggerMode"] = 1,
},
["useTooltip"] = false,
["keepAspectRatio"] = false,
["selfPoint"] = "CENTER",
["desc"] = "by 露露緹婭@Bilibili。\n\n特殊职责加载：团长、助理、治疗职责加载（骑士除外）。\n\n因为骑士职业角标可以看到大牺牲，团框上已设置好。\n如果需要单独使用这个WA查看大牺牲在团框上的情况，需要在触发器里取消对骑士的注释。\n\n转载请保留出处。",
