["Collapsing Star Indicator - Nameplate Text"] = {
["outline"] = "OUTLINE",
["wagoID"] = "-k80M3HlG",
["authorOptions"] = {
},
["preferToUpdate"] = true,
["customText"] = "function()\n    if aura_env.state and aura_env.state.unit then\n        local health1 = UnitHealth(aura_env.state.unit)\n        local health0 = UnitHealthMax(aura_env.state.unit)\n        local time\n        \n        if aura_env.states[2].expirationTime then\n            time = aura_env.states[2].expirationTime - GetTime()\n        elseif aura_env.states[3].expirationTime then\n            time = aura_env.states[3].expirationTime - GetTime()\n        elseif aura_env.states[4].expirationTime then\n            time = aura_env.states[4].expirationTime - GetTime()\n        elseif aura_env.states[5].expirationTime then\n            time = aura_env.states[5].expirationTime - GetTime()\n        elseif aura_env.states[6].expirationTime then\n            time = aura_env.states[6].expirationTime - GetTime()\n        elseif aura_env.states[7].expirationTime then\n            time = aura_env.states[7].expirationTime - GetTime()\n        elseif aura_env.states[8].expirationTime then\n            time = aura_env.states[8].expirationTime - GetTime()\n        end\n        \n        if time then\n            local doomcount\n            \n            if aura_env.states[9].matchCountPerUnit then\n                doomcount = aura_env.states[9].matchCountPerUnit\n            else\n                doomcount = 0\n            end\n            \n            local doomtime = 17344 * doomcount / health0 * 100\n            local timediff0 = health1 / health0 * 100 - time\n            local timediff1 = timediff0 - doomtime\n            local health = floor(timediff1 * health0 * 0.01)\n            \n            if timediff1 < 1 and timediff0 > -1 then\n                return string.format(\"|cff00ff00%.1f\", health * 0.001)..\"k\"\n            elseif timediff1 >= 1 then\n                return string.format(\"|cffffff00%.1f\", health * 0.001)..\"k\"\n            elseif timediff0 <= -1 then\n                return string.format(\"|cffff0000%.f\", timediff0 - 1)..\"s\"\n            end\n        end\n    end\nend",
