["trigger"] = {
["debuffType"] = "HELPFUL",
["type"] = "custom",
["customStacks"] = "",
["subeventSuffix"] = "_CAST_START",
["unit"] = "player",
["custom"] = "-- Secure Frame ! - Do not add anything that could change the frame - that could cause errors in combat\nfunction(sEvent, ...)    \n    if aura_env.config.tDebug.bDebug and aura_env.config.tDebug.bFramesBackdropEvents then\n        print(\"Backdrop\", aura_env.sFrameID, sEvent, ...)\n    end\n    if sEvent == \"MultiDotFrame_InitBackdrops\" then\n        aura_env.tData = select(1, ...)\n        aura_env.tData.fnInitDuplicateData()\n        \n        if aura_env.tZoneData then\n            aura_env.tData.fnSetupSecuredFrame()  \n        else\n            return false\n        end\n    elseif sEvent == \"MultiDotFrame_InitSharedTrigger_Backdrops\" then\n        aura_env.tTriggerData = select(1, ...)\n    else\n        if aura_env.tTriggerData then\n            return aura_env.tTriggerData.fnHandleTrigger(sEvent, ...)\n        end\n    end    \n    \n    return aura_env.bShown\nend",
["event"] = "Chat Message",
["subeventPrefix"] = "SPELL",
["customDuration"] = "function()\n    return aura_env.bFailedToTarget   \nend",
["spellIds"] = {
},
["events"] = "MultiDotFrame_ChangeZone MultiDotFrame_InitBackdrops MultiDotFrame_InitSharedTrigger_Backdrops",
