["init"] = {
["custom"] = "-- Loca Data zhTW Init\n-- This WA is only used to localize some of the strings used in other WAs\naura_env.sLocale = \"zhTW\"\n\nlocal tLocData = {}\naura_env.tLocData = tLocData\ntLocData.tLocalizations = {\n    -- Testing\n    [\"The Great Forge\"] = nil,\n    [\"War Quarter\"] = \"軍事區\",\n    [\"Valley of Honor\"] = nil,\n    [\"Heroic Training Dummy\"] = \"英雄訓練假人\",\n    [\"Grandmaster's Training Dummy\"] = \"宗師的訓練假人\",\n    [\"Expert's Training Dummy\"] = \"專家的訓練假人\",\n    [\"Master's Training Dummy\"] = \"大師的訓練假人\",\n    -- Sartharion\n    [\"The Obsidian Sanctum\"] = nil,\n    [\"Tenebron\"] = nil,\n    [\"Shadron\"] = nil,\n    [\"Vesperon\"] = nil,\n    -- Naxx\n    [\"The Horsemen's Assembly\"] = nil,\n    [\"Baron Rivendare\"] = nil,\n    [\"Thane Korth'azz\"] = nil,\n    [\"Lady Blaumeux\"] = nil,\n    -- Ulduar\n    [\"Formation Grounds\"] = nil,\n    [\"Flame Leviathan\"] = nil,\n    [\"The Colossal Forge\"] = \"巨熔爐\",\n    [\"Ignis the Furnace Master\"] = \"『火爐之主』伊格尼司\",\n    [\"Razorscale's Aerie\"] = \"銳鱗之巢\",\n    [\"Razorscale\"] = \"銳鱗\",\n    [\"The Scrapyard\"] = \"廢料場\",\n    [\"XT-002 Deconstructor\"] = \"XT-002拆解者\",\n    [\"The Celestial Planetarium\"] = \"星穹渾天儀\",\n    [\"Algalon the Observer\"] = \"『觀察者』艾爾加隆\",\n    [\"The Observation Ring\"] = \"觀察之環\",\n    [\"Auriaya\"] = \"奧芮雅\",\n    [\"The Halls of Winter\"] = \"凜冬之廳\",\n    [\"Hodir\"] = \"霍迪爾\",\n    [\"The Clash of Thunder\"] = \"雷鳴之廳\",\n    [\"Thorim\"] = \"索林姆\",\n    [\"The Descent into Madness\"] = \"驟狂斜廊\",\n    [\"General Vezax\"] = \"威札斯將軍\",\n    [\"The Prison of Yogg-Saron\"] = \"尤格薩倫之獄\",\n    [\"Yogg-Saron\"] = \"尤格薩倫\",\n    [\"The Assembly of Iron\"] = \"鐵之集會所\",\n    [\"Stormcaller Brundir\"] = \"風暴召喚者布倫迪爾\",\n    [\"Runemaster Molgeim\"] = \"符文大師墨吉姆\",\n    [\"Steelbreaker\"] = \"破鋼者\",\n    [\"The Shattered Walkway\"] = \"破碎走道\",\n    [\"Right Arm\"] = \"右臂\",\n    [\"Kologarn\"] = \"柯洛剛恩\",\n    [\"Left Arm\"] = \"左臂\",\n    [\"The Conservatory of