 Darkbane\"] = \"艾狄絲·暗寂\",\n    [\"The Icy Depths\"] = \"冰結深淵\",\n    [\"Anub'arak\"] = \"阿努巴拉克\",\n    [\"Nerubian Burrower\"] = \"奈幽掘洞者\",\n    [\"Onyxia's Lair\"] = \"奧妮克希亞的巢穴\",\n    [\"Onyxia\"] = \"奧妮克希亞\",\n    [\"Onyxian Lair Guard\"] = \"奧妮克希亞守衛\",\n    -- ICC\n    [\"The Spire\"] = \"冰冠尖塔\",\n    [\"Lord Marrowgar\"] = \"瑪洛嘉領主\",\n    [\"Bone Spike\"] = \"骸骨尖刺\",\n    [\"Oratory of the Damned\"] = \"詛咒祈願室\",\n    [\"Lady Deathwhisper\"] = \"亡語女士\",\n    [\"Cult Adherent\"] = \"神教擁護者\",\n    [\"Cult Fanatic\"] = \"神教狂熱者\",\n    [\"Rampart of Skulls\"] = \"骸顱壁壘\",\n    [\"Muradin Bronzebeard\"] = \"穆拉丁·銅鬚\",\n    [\"High Overlord Saurfang\"] = \"薩魯法爾霸王\",\n    [\"Deathbringer's Rise\"] = \"死亡使者高崗\",\n    [\"Deathbringer Saurfang\"] = \"死亡使者薩魯法爾\",\n    [\"Blood Beast\"] = \"血獸\",\n    [\"The Plagueworks\"] = \"瘟疫工坊\",\n    [\"Festergut\"] = \"爛腸\",\n    [\"Rotface\"] = \"腐臉\",\n    [\"Little Ooze\"] = \"小軟泥怪\",\n    [\"Putricide's Laboratory of Alchemical Horrors and Fun\"] = \"普崔希德的恐懼與歡樂鍊金實驗室\",\n    [\"Volatile Ooze\"] = \"暴躁軟泥怪\",\n    [\"Professor Putricide\"] = \"普崔希德教授\",\n    [\"Gas Cloud\"] = \"毒氣雲\",\n    [\"The Crimson Hall\"] = \"赤紅大廳\",\n    [\"Prince Taldaram\"] = \"泰爾達朗親王\",\n    [\"Prince Keleseth\"] = \"凱雷希斯親王\", \n    [\"Prince Valanar\"] = \"瓦拉納爾親王\",\n    [\"The Sanctum of Blood\"] = \"血之聖所\",\n    [\"Blood-Queen Lana'thel\"] = \"血腥女王菈娜薩爾\",\n    [\"The Frostwing Halls\"] = \"霜翼大廳\",\n    [\"Valithria Dreamwalker\"] = \"瓦莉絲瑞雅·夢行者\",\n    [\"Gluttonous Abomination\"] = \"貪吃的憎惡體\",\n    [\"Risen Archmage\"] = \"復活的大法師\",\n    [\"Suppresser\"] = \"抑制者\",\n    [\"The Frost Queen's Lair\"] = \"霜翼之巢\",\n    [\"Sindragosa\"] = \"辛德拉苟莎\",\n    [\"The Frozen Throne\"] = \"冰封王座\",\n    [\"The Lich King\"] = \"巫妖王\",\n    [\"Shambling Horror\"] = \"蹣跚的恐獸\",\n    [\"Ice Sphere\"] = nil,\n    [\"Raging Spirit\"] = nil,\n    [\"Val'kyr Shadowguard\"] = nil,\n}\n\n\n\nlocal function LocalizeTable(tTableToLocalize)\n    if tTableToLocalize.bLocalized then return tTableToLocalize end\n    \n    local tLocalizedTable = {\n        bLocalized = GetLocale(),\n        \n    }\n    \n    local function LocalizeField(tIn, tOut, sKey)\n        local sLocalizedKey = sKey\n        if tLocData.tLocalizations[sKey] and tLocData.tLocalizations[sKey] then\n            sLocalizedKey = tLocData.tLocalizations[sKey]\n        end\n        \n        if type(tIn[sKey]) == \"table\" then\n            tOut[sLocalizedKey] = {}\n            \n            for k,_ in pairs(tIn[sKey]) do\n                LocalizeField(tIn[sKey], tOut[sLocalizedKey], k)\n            end\n        else\n            if tLocData.tLocalizations[tIn[sKey]] and tLocData.tLocalizations[tIn[sKey]] then\n                tOut[sLocalizedKey] = tLocData.tLocalizations[tIn[sKey]]\n            else\n                tOut[sLocalizedKey] = tIn[sKey]\n            end\n        end\n    end\n    \n    for k,_ in pairs(tTableToLocalize) do\n        LocalizeField(tTableToLocalize, tLocalizedTable, k)\n    end\n    \n    return tLocalizedTable\nend\ntLocData.fnLocalizeTable = LocalizeTable\n\nlocal function InitLoca()\n    if GetLocale() == aura_env.sLocale then\n        WeakAuras.ScanEvents(\"MultiDotFrame_Localize\", tLocData)\n    end\nend\naura_env.fnInitLoca = InitLoca\n\nInitLoca()",
