},
["custom"] = "function(allStates, sEvent, ...)\n    if aura_env.config.tDebug.bDebug and aura_env.config.tDebug.bFramesHPBarEvents then\n        print(\"HP\", aura_env.sFrameID, sEvent, ...)\n    end\n    \n    if sEvent == \"MultiDotFrame_InitHPBars\" then\n        aura_env.tData = select(1, ...)\n        aura_env.tData.fnInitDuplicateData()\n        if aura_env.tZoneData and aura_env.tData.CheckNameplatesForNPC(allStates) then\n            return true    \n        end\n    elseif sEvent == \"MultiDotFrame_InitSharedTrigger_HPBars\" then\n        aura_env.tTriggerData = select(1, ...)\n    else\n        if aura_env.tTriggerData then\n            return aura_env.tTriggerData.fnHandleTrigger(allStates, sEvent, ...)\n        end\n    end\n    \n    return false\nend\n\n\n",
