["init"] = {
["custom"] = "-- Class Data Default Init\nlocal tAuraData = {}\naura_env.sPlayerClass = select(2, UnitClass(\"player\"))\nlocal tClassesWithoutAura = {\n    [\"WARRIOR\"] = true,\n    [\"DEATHKNIGHT\"] = true,\n    [\"ROGUE\"] = true,\n    [\"PALADIN\"] = true\n}\nif not tClassesWithoutAura[aura_env.sPlayerClass] then\n    aura_env.sPlayerClass = nil\nend\n\ntAuraData.tDotAuras = {\n    -- To Fill\n    --[172] = \"Corruption\",\n}\ntAuraData.tDamageTriggers = {\n    -- To Fill\n    --[686] = \"Shadow Bolt\",\n}\n\ntAuraData.tDamageInfos = {\n    -- To Fill\n    --[[\n    [\"Shadow Bolt\"] = {\n        tRefreshAura = {\n            tRefreshTalent = {\n                iRow = 1,\n                iIndex = 24,\n            },\n            tAuras = {\n\"Corruption\",\n}\n        }\n    },\n]]--\n}\n\ntAuraData.tSpellsInfos = {\n    -- To Fill\n    --[[\n    [\"Corruption\"] = {\n        iDuration = 18,\n        sName = \"Corruption\",\n        sGroup = \"Corruption\",\n        iIcon = 136118,\n        bAffectedByHasteFromGlyph = 237651,\n    },\n]]--\n}\n\ntAuraData.fExecuteRange = 0\n\ntAuraData.tCastingModeBindings = aura_env.config.tCastingModeBindings.tOther\ntAuraData.tBlacklist = {}\n\nlocal function SendAuraData()\n    WeakAuras.ScanEvents(\"MultiDotFrame_AuraData\", tAuraData, aura_env.sPlayerClass)\nend\n\naura_env.fnSendAuraData = SendAuraData\n\n",
["do_custom"] = true,
},
