["【猎人】生存猎自动切换追踪助手（国服修复版，默认禁用，手动加载）"] = {
["outline"] = "OUTLINE",
["wagoID"] = "jsWAPs3a7",
["parent"] = "!【露露】可选组 1114更",
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "\naura_env.TRACKING_CONFIG = {\n    -- 战斗追踪技能\n    [\"野兽\"]       = {name = \"追踪野兽\",    spellID = 19884},\n    [\"人型生物\"]    = {name = \"追踪人型生物\", spellID = 19878},\n    [\"亡灵\"]       = {name = \"追踪亡灵\",    spellID = 19883},\n    [\"元素生物\"]    = {name = \"追踪元素生物\", spellID = 19880},\n    [\"巨人\"]       = {name = \"追踪巨人\",    spellID = 19882},\n    [\"恶魔\"]       = {name = \"追踪恶魔\",    spellID = 19879},\n    [\"龙类\"]       = {name = \"追踪龙类\",    spellID = 19885},\n    \n    -- 专业追踪技能\n    [\"矿物\"]       = {name = \"寻找矿物\",    spellID = 2580,  index = 2},\n    [\"渔点\"]       = {name = \"寻找渔点\",    spellID = 43308, index = 1}\n}\n\naura_env.castTracking = function(skillName)\n    if not skillName then return false end\n    \n\n    for i = 1, C_Minimap.GetNumTrackingTypes() do\n        local info = C_Minimap.GetTrackingInfo(i)\n        if info and info.name == skillName then\n            if info.active then\n                \n                return false\n            end\n            break\n        end\n    end\n    \n    \n    CastSpellByName(skillName)\n    \n    return true\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "timed",
["events"] = "PLAYER_TARGET_CHANGED",
["custom"] = "\nfunction()\n     if UnitExists(\"target\") and not UnitIsDead(\"target\") and UnitCanAttack(\"player\", \"target\") then\n        local targetType = UnitCreatureType(\"target\")\n        \n        local tracking = targetType and aura_env.TRACKING_CONFIG[targetType]\n        if tracking then\n            return aura_env.castTracking(tracking.name)\n        end\n    end\n    \n    \n    return aura_env.castTracking(aura_env.TRACKING_CONFIG[\"矿物\"].name)\nend",
["subeventPrefix"] = "SPELL",
