["customGrow"] = "function(newPositions, activeRegions)\n    local count = #activeRegions\n    local iMargin = 1\n    local iHeight = 12\n    if count > 0 then \n        if activeRegions[1].data.config.bClassicBarDynamicHeight then \n            local iFrameHeight = 62\n            iHeight = iFrameHeight / count\n        else \n            iHeight = activeRegions[1].data.config.iClassicBarHeight or 12\n        end\n    end\n    \n    for i = 1, count do\n        newPositions[i] = {\n            0,\n            iMargin + (iHeight + iMargin) * (i - 1),\n            \n        }\n        \n        activeRegions[i].region:SetRegionHeight(iHeight)\n    end\nend\n\n",
