{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "custom",
["custom"] = "function(_,_,event,_,sourceGUID,_,_,_,_,_,_,_,_,spellName,_,_,_,_,_,_,_,critical)\n    if (sourceGUID == UnitGUID(\"player\")) then\n        if event == \"SPELL_DAMAGE\" then\n            if (\n                spellName == aura_env.fireball or \n                spellName == aura_env.fireBlast or \n                spellName == aura_env.scorch or \n                spellName == aura_env.livingBomb or \n                spellName == aura_env.frostfireBolt\n            ) then\n                if critical then\n                    return true\n                end\n            end\n            \n        end\n    end\nend\n\n\n\n\n\n\n",
["events"] = "COMBAT_LOG_EVENT_UNFILTERED",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["custom_type"] = "event",
["spellIds"] = {
},
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
["custom"] = "function(_,_,event,_,sourceGUID,_,_,_,_,_,_,_,_,spellName,_,_,_,_,_,_,_,critical)\n    if (sourceGUID == UnitGUID(\"player\")) then\n        \n        if event == \"SPELL_DAMAGE\" then\n            if (\n                spellName == aura_env.fireball or \n                spellName == aura_env.fireBlast or \n                spellName == aura_env.scorch or \n                spellName == aura_env.livingBomb or \n                spellName == aura_env.frostfireBolt\n            ) then\n                if not critical then\n                    return true\n                end\n            end\n            \n        elseif event == \"SPELL_AURA_APPLIED\" or event == \"SPELL_AURA_REFRESH\"then\n            if spellName == aura_env.hotStreak then\n                return true\n            end\n        end\n    end\nend\n\n\n\n\n\n\n\n",
},
},
