["authorOptions"] = {
{
["type"] = "description",
["text"] = "|cFF6666FFJeyp's Boss Frames|r",
["fontSize"] = "medium",
["width"] = 2,
},
{
["type"] = "description",
["text"] = "|cFFFF6666Important |r: Always update your options when having the top most group of the WA selected (Jeyp's Boss Frames) to avoid desyncing the values.",
["fontSize"] = "medium",
["width"] = 2,
},
{
["type"] = "space",
["variableWidth"] = true,
["height"] = 1,
["width"] = 2,
["useHeight"] = false,
},
{
["desc"] = "|cFF6666FFClassic Skin|r : Progress bars showing the status of all DoTs in a visual way.|n|cFF66FF66Alternative Skin|r : Made by Solah. More compact and uses Icons to display the status of DoTs.",
["type"] = "select",
["values"] = {
"Classic",
"Alternative",
},
["default"] = 1,
["key"] = "iSkin",
["useDesc"] = true,
["name"] = "Skin",
