},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- This WA is used to handle trigger logic of the HP Bars at a single location.\n\nlocal tBackdropTrigger = {}\n\nlocal function HandleTrigger(sEvent, ...)\n    if sEvent == \"MultiDotFrame_ChangeZone\" then\n        local tZoneData = select(2, ...)\n        if tZoneData == nil or tZoneData[aura_env.sFrameID] == nil then return false end\n        aura_env.tZoneData = tZoneData[aura_env.sFrameID]\n        \n        if aura_env.tData then\n            aura_env.tData.fnSetupSecuredFrame()  \n        else\n            return false\n        end\n    end\n    \n    if aura_env.clickableFrame then\n        if aura_env.tTriggerData.iSkin ~= aura_env.iSkinID then\n            --Can only change out of combat, so shouldn't affect Secured Frames\n            if aura_env.bShown then\n                aura_env.bShown = false\n            end\n            return false\n        else\n            if not aura_env.bShown then\n                aura_env.bShown = true\n            end\n        end\n    end\n    return true\nend\ntBackdropTrigger.fnHandleTrigger = HandleTrigger \n\nlocal function Init()\n    tBackdropTrigger.iSkin = aura_env.config.iSkin\n    WeakAuras.ScanEvents(\"MultiDotFrame_InitSharedTrigger_Backdrops\", tBackdropTrigger)\nend\naura_env.fnInit = Init\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
