["init"] = {
["custom"] = "local tZonesData = {}\ntZonesData.sName = \"T8\"\ntZonesData.tBlacklist = aura_env.config.tNPCBlackList.tT8\ntZonesData.tZones = {\n    [\"Formation Grounds\"] = {\n        [\"A\"] = {\n            sNPCID = \"33113\",\n            sTarName = \"Flame Leviathan\",\n            iIcon = 254102,\n            tEnabledOptions = {\n                \"bFlameLeviathanFight\", \n                \"bFlameLeviathan\",\n            },\n        },\n    },\n    [\"The Colossal Forge\"] = {\n        [\"A\"] = {\n            sNPCID = \"33118\",\n            sTarName = \"Ignis the Furnace Master\",\n            iIcon = 254092,\n            tEnabledOptions = {\n                \"bIgnisFight\", \n                \"bIgnis\",\n            },\n        },\n    },\n    [\"Razorscale's Aerie\"] = {\n        [\"A\"] = {\n            sNPCID = \"33186\",\n            sTarName = \"Razorscale\",\n            iIcon = 298670,\n            tEnabledOptions = {\n                \"bRazorscaleFight\", \n                \"bRazorscale\",\n            },\n        },\n    },\n    [\"The Scrapyard\"] = {\n        [\"A\"] = {\n            sNPCID = \"33293\",\n            sTarName = \"XT-002 Deconstructor\",\n            iIcon = 254104,\n            tEnabledOptions = {\n                \"bXTFight\", \n                \"bXT\",\n            },\n        },\n        [\"B\"] = {\n            sNPCID = \"34004\",\n            sTarName = \"Life Spark\",\n            iIcon = 136050,\n            tEnabledOptions = {\n                \"bXTFight\", \n                \"bLifeSpark\",\n            },\n        },\n        [\"C\"] = {\n            sNPCID = \"33344\",\n            sTarName = \"XM-024 Pummeller\",\n            iIcon = 132996,\n            tEnabledOptions = {\n                \"bXTFight\", \n                \"bPummeller\",\n            },\n        },\n    },\n    [\"The Assembly of Iron\"] = {\n        [\"A\"] = {\n            sNPCID = \"32857\",\n            sTarName = \"Stormcaller Brundir\",\n            iIcon = 254108,\n            tEnabledOptions = {\n                \"bIronCouncilFight\", \n                \"bStormcaller\",\n            },\n        },\n        [\"B\"] = {     \n            sNPCID = \"32927\",\n            sTarName = \"Runemaster Molgeim\",\n            iIcon = 237375,\n            tEnabledOptions = {\n                \"bIronCouncilFight\", \n                \"bRunemaster\",\n            },\n        },\n        [\"C\"] = {     \n            sNPCID = \"32867\",\n            sTarName = \"Steelbreaker\",\n            iIcon = 254110,\n            tEnabledOptions = {\n                \"bIronCouncilFight\", \n                \"bSteelbreaker\",\n            },\n        },\n    },\n    [\"The Celestial Planetarium\"] = {\n        [\"A\"] = {\n            sNPCID = \"32871\",\n            sTarName = \"Algalon the Observer\",\n            iIcon = 254087,\n            tEnabledOptions = {\n                \"bAlgalonFight\", \n                \"bAlgalon\",\n            },\n        },\n        bIsSingleBoss = true,\n    },\n    [\"The Shattered Walkway\"] = {\n        [\"A\"] = {\n            sNPCID = \"32934\",\n            sTarName = \"Right Arm\",\n            iIcon = 236314,\n            tEnabledOptions = {\n                \"bKologarnFight\", \n                \"bRightArm\",\n            },\n        },\n        [\"B\"] = {     \n            sNPCID = \"32930\",\n            sTarName = \"Kologarn\",\n            iIcon = 254095,\n            tEnabledOptions = {\n                \"bKologarnFight\", \n                \"bKologarn\",\n            },\n        },\n        [\"C\"] = {     \n            sNPCID = \"32933\",\n            sTarName = \"Left Arm\",\n            iIcon = 136101,\n            tEnabledOptions = {\n                \"bKologarnFight\", \n                \"bLeftArm\",\n            },\n        },\n    },\n    [\"The Observation Ring\"] = {\n        [\"A\"] = {\n            sNPCID = \"33515\",\n            sTarName = \"Auriaya\",\n            iIcon = 254088,\n            tEnabledOptions = {\n                \"bAuriayaFight\", \n                \"bAuriaya\",\n            },\n        },\n        [\"B\"] = {\n            sNPCID = \"34035\",\n            sTarName = \"Feral Defender\",\n            iIcon = 132225,\n            tEnabledOptions = {\n                \"bAuriayaFight\", \n                \"bFeralDefender\",\n            },\n        },\n    },\n    [\"The Halls of Winter\"] = {\n        [\"A\"] = {\n            sNPCID = \"32845\",\n            sTarName = \"Hodir\",\n            iIcon = 254091,\n            tEnabledOptions = {\n                \"bHodirFight\", \n                \"bHodir\",\n            },\n        },\n    },\n    [\"The Clash of Thunder\"] = {\n        [\"A\"] = {\n            sNPCID = \"32865\",\n            sTarName = \"Thorim\",\n            iIcon = 298676,\n            tEnabledOptions = {\n                \"bThorimFight\", \n                \"bThorim\",\n            },\n        },\n    },\n    [\"The Conservatory of Life\"] = {\n        [\"A\"] = {\n            sNPCID = \"32916\",\n            sTarName = \"Snaplasher\",\n            iIcon = 134196,\n            tEnabledOptions = {\n                \"bFreyaFight\", \n                \"bSnaplasher\",\n            },\n        },\n        [\"B\"] = {     \n            sNPCID = \"32919\",\n            sTarName = \"Storm Lasher\",\n            iIcon = 135990,\n            tEnabledOptions = {\n                \"bFreyaFight\", \n                \"bStormLasher\",\n            },\n        },\n        [\"C\"] = {     \n            sNPCID = \"33202\",\n            sTarName = \"Ancient Water Spirit\",\n            iIcon = 135862,\n            tEnabledOptions = {\n                \"bFreyaFight\", \n                \"bAncientWaterSpirit\",\n            },\n        },\n        [\"D\"] = {     \n            sNPCID = \"32906\",\n            sTarName = \"Freya\",\n            iIcon = 254089,\n            tEnabledOptions = {\n                \"bFre