["屏蔽罗宁的喊话和语音"] = {
["outline"] = "OUTLINE",
["wagoID"] = "koLJP9I4E",
["parent"] = "【工具】闭嘴吧，罗宁！（by 夏洛克）",
["preferToUpdate"] = true,
["customText"] = "function()\n    return \"\"\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local table_insert = tinsert\nlocal table_remove = tremove\nlocal string_format = string.format\nlocal string_sub = string.sub\n\nlocal env = aura_env\nlocal cfg = aura_env.config\nlocal data = _G[\"WA_\"..aura_env.id] or {}\n_G[\"WA_\"..aura_env.id] = data\n\nlocal function getDate()\n    -- Date format: 2023-05-25\n    local str = date(\"%Y-%m-%d\")\n    return str\nend\n\nlocal settings = {\n    -- Config\n    mute_rhonin_voice = true,\n    block_rhonin_yell = false,\n    allow_random_yell = false,\n    next_random = -1,\n    random_probability = 10,    -- [0, 100]\n    allow_times_perday = 1,\n    date_today = getDate(),\n    yelled_times_today = 0,\n    allowed_yell_times_today = 0,\n    -- About filter\n    cur_filter = {},\n    chatFilters = {},\n    lastLineId = -1,\n    lastBlocked = false,\n    -- Sound setting\n    Sound_EnableDialog = nil,\n    sound_muted = false,\n}\n\nenv.loaded = false\nenv.initialized = nil\nenv.settings = settings\n\n--\n-- http://db.nfuwow.com/80/?npc=16128#sounds\n--\nlocal rhoninSoundFiles = {\n    545431, --sound/creature/brann/ur_brann_dalaran01.ogg\n    559130, --sound/creature/rhonin/ur_rhonin_event01.ogg\n    559131, --sound/creature/rhonin/ur_rhonin_event02.ogg\n    559126, --sound/creature/rhonin/ur_rhonin_event03.ogg\n    559128, --sound/creature/rhonin/ur_rhonin_event04.ogg\n    559133, --sound/creature/rhonin/ur_rhonin_event05.ogg\n    559129, --sound/creature/rhonin/ur_rhonin_event06.ogg\n    559132, --sound/creature/rhonin/ur_rhonin_event07.ogg\n    559127, --sound/creature/rhonin/ur_rhonin_event08.ogg\n}\n\nlocal rhoninLocaleName = {\n    [\"enUS\"] = \"Rhonin\",\n    [\"deDE\"] = \"Rhonin\",\n    [\"esES\"] = \"Rhonin\",\n    [\"frFR\"] = \"Rhonin\",\n    [\"ruRU\"] = \"Ронин\",\n    [\"zhCN\"] = \"罗宁\",\n    [\"zhTW\"] = \"羅甯\",\n}\n\nlocal rhoninLocaleStartTip = {\n    [\"enUS\"] = \"started a speech, this is his |cFF40FB40%dth|r shout today.\",\n    [\"zhCN\"] = \"开始了一段演讲，这是他今天的第 |cFF40FB40%d|r 次喊话。\",\n    [\"zhTW\"] = \"開始了一段演講，這是他今天的第 |cFF40FB40%d|r 次喊話。\",\n}\n\nlocal rhoninLocaleEndTip = {\n    [\"enUS\"] = \"ended a speech, this is his |cFF40FB40%dth|r shout today.\",\n    [\"zhCN\"] = \"结束了一段演讲，这是他今天的第 |cFF40FB40%d|r 次喊话。\",\n    [\"zhTW\"] = \"結束了一段演講，這是他今天的第 |cFF40FB40%d|r 次喊話。\",\n}\n\n--\n-- http://db.nfuwow.com/80/?npc=16128#sai-actionlist-1612802\n--\nlocal rhoninLocaleYellSpeeches = {\n    [\"enUS\"] = { -- English\n        \"We received Brann's message, and we have begun preparations.\",\n        \"Citizens of Dalaran! Raise your eyes to the skies and observe!\",\n        \"Today our world's destruction has been averted in defiance of our very makers!\",\n        \"Algalon the Observer, herald of the titans, has been defeated by our brave comrades in the depths of the titan city of Ulduar.\",\n        \"Algalon was sent here to judge the fate of our world.\",\n        \"He found a planet whose races had deviated from the titans' blueprints. A planet where not everything had gone according to plan.\",\n        \"Cold logic deemed our world not worth saving. Cold logic, however, does not account for the power of free will. It's up to each of us to prove this is a world worth saving.\",\n        \"That our lives... our lives are worth living.\",\n    },\n    [\"deDE\"] = { -- German\n        \"Wir haben Branns Nachricht erhalten und mit Vorbereitungen begonnen.\",\n        \"Bürger von Dalaran! Richtet Eure Blicke gen Himmel und beobachtet aufmerksam!\",\n        \"Heute wurde die Zerstörung dieser Welt abgewendet, im Widerstand gegen unsere eigenen Schöpfer!\",\n        \"Algalon der Beobachter, Herold der Titanen, wurde von unseren tapferen Kameraden in den Tiefen der Titanenstadt Ulduar bezwungen.\",\n        \"Algalon wurde zu uns gesandt, um über diese Welt zu richten.\",\n        \"Er fand eine Welt vor, deren Völker nicht mehr den Blaupausen der Titanen entsprachen. Eine Welt, in der nicht alles nach Plan gelaufen war.\",\n        \"Kalte Logik befand unseren Planeten nicht der Rettung würdig. Jedoch trägt Logik nicht der Macht des freien Willens Rechnung. Es ist an uns, zu beweisen, dass diese Welt es wert ist, gerettet zu werden.\",\n        \"Dass unsere Leben es wert sind... gelebt zu werden.\",\n    },\n    [\"esES\"] = { -- Spanish\n        \"Recibimos el mensaje de Brann y hemos comenzado con los preparativos.\",\n        \"¡Ciudadanos de Dalaran! ¡Alzad la vista al cielo y observad!\",\n        \"Hoy hemos evitado la destrucción de nuestro mundo desafiando a nuestros propios creadores.\",\n        \"Nuestros valientes camaradas han derrotado al heraldo de los titanes, Algalon el Observador, en las profundidades de Ulduar, la ciudad de los titanes.\",\n        \"Algalon, fue enviado aquí para juzgar el futuro de nuestro mundo.\",\n        \"Encontró un planeta cuyas razas se habían desviado de los planes de los titanes. Un planeta en el que no todo había ido según lo planeado.\",\n        \"La fría lógica consideró que nuestro planeta no merece ser salvado. La fría lógica, sin embargo, no contó con el poder del libre albedrío. Depende de cada uno de nosotros demostrar que este es un mundo que vale la pena salvar.\",\n        \"Que nuestras vidas… son vidas que vale la pena vivir.\",\n    },\n    [\"frFR\"] = { -- French\n        \"Nous avons reçu le message de Brann, et nous avons entamé les préparatifs.\",\n        \"Citoyens de Dalaran ! Levez les yeux vers le ciel et regardez bien !\",\n        \"En ce jour, la destruction de notre monde a été évitée, au grand dam de nos propres créateurs !\",\n        \"Algalon l'Observateur, héraut des titans, a été vaincu par nos braves camarades dans les profondeurs de la cité d'Ulduar.\",\n        \"Algalon avait été envoyé parmi nous pour juger du sort du monde.\",\n        \"Il a trouvé un monde où les peuples s'étaient écartés du modèle des titans. Un monde sur lequel tout ne s'était pas déroulé conformément au plan.\",\n        \"L'implacable logique voulait que notre monde ne mérite pas d'être sauvé. Mais cette logique ne prend pas en compte la puissance du libre arbitre. C'est à chacun de nous qu'il revient de prouver que ce monde mérite son salut.\",\n        \"Que nos vies... Méritent d'être vécues.\",\n    },\n    [\"ruRU\"] = { -- Russian\n        \"Мы получили сообщение Бранна и начали подготовку.\",\n        \"Жители Даларана! Поднимите глаза и взгляните на это небо!\",\n        \"Сегодня, чтобы предотвратить гибель мира, пришлось противостоять самим его создателям!\",\n        \"Наши бравые герои в глубинах Ульдуара, обители титанов, одолели их вестника, Наблюдателя Алгалона.\",\n        \"Он был послан, чтобы решить судьбу нашего мира.\",\n        \"Мира, обитатели которого не стали следовать шаблону титанов. Планеты, чье развитие отклонилось от изначального плана.\",\n        \"С точки зрения логики наша планета не имеет права на существование. Но холодная логика не берет в расчет силу свободной воли. И теперь дело каждого – доказать, что наш мир заслуживает спасения.\",\n        \"Что мы живем... не напрасно.\",\n    },\n    [\"zhCN\"] = { -- Simplified Chinese\n        \"我们收到了布莱恩的消息，已经开始着手做准备了。\",\n        \"达拉然的公民们！抬起你们的头，仰望天空吧！\",\n        \"今天，我们所生活的这个世界，险些被它的缔造者毁灭！\",\n        \"我们勇敢的伙伴们深入泰坦之城奥杜尔，击败了观察者奥尔加隆，泰坦派来的使者！\",\n        \"奥尔加隆前来决定我们这个世界的命运。\",\n        \"他发现，在这个世界中，人们并不接受泰坦设计的蓝图。在这个世界中，并非一切都按照计划完美运行。\",\n        \"冷酷的逻辑推论出：我们的世界不值得拯救。但是，它并没有考虑到自由意志的力量。我们每一个人都有责任证明，这是一个值得拯救的世界。\",\n        \"因为我们的生命……是值得延续的生命。\",\n    },\n    [\"zhTW\"] = { -- Traditional Chinese\n        \"布蘭\",\n        \"達拉然\",\n        \"今天\",\n        \"生命\",\n    },\n}\n\nlocal rhoninName = rhoninLocaleName[GetLocale()] or \"Rhonin\"\nlocal rhoninYellSpeeches = rhoninLocaleYellSpeeches[GetLocale()] or rhoninLocaleYellSpeeches[\"enUS\"]\n\nlocal rhoninStartTip = rhoninLocaleStartTip[GetLocale()] or rhoninLocaleStartTip[\"enUS\"]\nlocal rhoninEndTip = rhoninLocaleEndTip[GetLocale()] or rhoninLocaleEndTip[\"enUS\"]\n\nlocal function to_string(obj)\n    local str\n    if type(obj) == 'string' then\n        str = '\"'..obj..'\"'\n    elseif type(obj) == 'nil' then\n        str = '<nil>'\n    elseif type(obj) == 'table' then\n        str = \"<table>\"\n    else\n        -- number, boolean, function ....\n        str = tostring(obj)\n    end\n    return str\nend\n\nlocal function printf(fmt, ...)\n    local str = string.format(fmt, ...)\n    print(str)\nend\n\nlocal WriteConfigs = function()\n    if not cfg then return end\n    cfg.block_rhonin_yell = settings.block_rhonin_yell\n    cfg.mute_rhonin_voice = settings.mute_rhonin_voice\n    if cfg.options_allow_random ~= nil then\n        cfg.options_allow_random.allow_random_yell = settings.allow_random_yell\n        cfg.options_allow_random.random_probability = settings.random_probability\n    end\n    if cfg.options_allow_times ~= nil then\n        cfg.options_allow_times.allow_times_perday = settings.allow_times_perday\n    end\nend\n\nlocal ReadFromConfigs = function()\n    if not cfg then return end\n    settings.block_rhonin_yell = cfg.block_rhonin_yell\n    settings.mute_rhonin_voice = cfg.mute_rhonin_voice\n    if cfg.options_allow_random ~= nil then\n        settings.allow_random_yell = cfg.options_allow_random.allow_random_yell\n        settings.random_probability = cfg.options_allow_random.random_probability\n    end\n    if cfg.options_allow_times ~= nil then\n        settings.allow_times_perday = cfg.options_allow_times.allow_times_perday\n    end\nend\n\nlocal SyncOptions = function(allstates)\n    ReadFromConfigs()\n    \n    return true\nend\n\nlocal LoadSession = function()\n    aura_env.saved = aura_env.saved or {}\n    local db = aura_env.saved[WeakAuras.me]\n    if not db then return end\n    \n    if db.block_rhonin_yell ~= nil then\n        settings.block_rhonin_yell = db.block_rhonin_yell\n    end\n    if db.mute_rhonin_voice ~= nil then\n        settings.mute_rhonin_voice = db.mute_rhonin_voice\n    end\n    if db.allow_random_yell ~= nil then\n        settings.allow_random_yell = db.allow_random_yell\n    end\n    if db.random_probability ~= nil then\n        settings.random_probability = ((db.random_probability <= 100) and db.random_probability) or 100\n    end\n    if db.allow_times_perday ~= nil then\n        settings.allow_times_perday = db.allow_times_perday\n    end\n    \n    if not db.date_today then\n        if (db.date_today ~= \"\") and (settings.date_today == db.date_today) then\n            if not db.yelled_times_today then\n                settings.yelled_times_today = db.yelled_times_today\n            end\n            if not db.allowed_yell_times_today then\n                settings.allowed_yell_times_today = db.allowed_yell_times_today\n            end\n        end\n    end\n    \n    ReadFromConfigs()\nend\n\nlocal SaveSession = function()\n    aura_env.saved = aura_env.saved or {}\n    aura_env.saved[WeakAuras.me] = {}\n    local db = aura_env.saved[WeakAuras.me]\n    \n    ReadFromConfigs()\n    \n    db.block_rhonin_yell = settings.block_rhonin_yell\n    db.mute_rhonin_voice = settings.mute_rhonin_voice\n    \n    db.allow_random_yell = settings.allow_random_yell\n    db.random_probability = settings.random_probability\n    db.allow_times_perday = settings.allow_times_perday\n    \n    db.date_today = settings.date_today\n    db.yelled_times_today = settings.yelled_times_today\n    db.allowed_yell_times_today = settings.allowed_yell_times_today\nend\n\nlocal function NeedShoutUpRhonin()\n    if (settings.allow_random_yell and (settings.next_random > settings.random_probability)) or ((not settings.allow_random_yell) and (settings.allowed_yell_times_today > settings.allow_times_perday)) then\n        return true\n    else\n        return false\n    end\nend\n\nlocal function NeedShoutUpRhoninYell()\n    if settings.block_rhonin_yell or ((not settings.block_rhonin_yell) and (not settings.mute_rhonin_voice) and NeedShoutUpRhonin()) then\n        return true\n    else\n        return false\n    end\nend\n\nlocal function NeedShoutUpRhoninVoice()\n    if settings.mute_rhonin_voice or ((not settings.mute_rhonin_voice) and NeedShoutUpRhonin()) then\n        return true\n    else\n        return false\n    end\nend\n\nlocal function MuteRhoninSoundFiles(needMute)\n    if needMute then\n        for _, soundFid in pairs(rhoninSoundFiles) do\n            MuteSoundFile(soundFid)\n        end\n        settings.sound_muted = true\n    else\n        for _, soundFid in pairs(rhoninSoundFiles) do\n            UnmuteSoundFile(soundFid)\n        end\n        settings.sound_muted = false\n    end\nend\n\nlocal function MuteRhoninVoiceIfNeed()\n    if settings.mute_rhonin_voice then\n        MuteRhoninSoundFiles(true)\n    else\n        MuteRhoninSoundFiles(false)\n    end\nend\n\nlocal function IsRhoninYellWords(message)\n    local index = 1\n    for _, words in pairs(rhoninYellSpeeches) do\n        if message:find(words) then\n            return true, index\n        end\n        index = index + 1\n    end\n    return false, index\nend\n\nlocal function ChatFrame_NonsterYellFilter(self, event, message, author, languageName, channelName, target, specialFlags, zoneChannelId, channelIndex, channelBaseName, languageId, lineId, guid, bnSenderId, isMobile, isSubtitle, hideSenderInLetterbox, supressRaidIcons)\n    if lineId ~= settings.lastLineId then\n        local needBlocked = false\n        settings.lastLineId = lineId\n        if (author == rhoninName) then\n            local isRhoninWords, wordIndex = IsRhoninYellWords(message)\n            if (isRhoninWords) then\n                if (wordIndex == 2) then\n                    if settings.next_random < 0 then\n                        settings.next_random = random(100)\n                    end\n                    settings.yelled_times_today = settings.yelled_times_today + 1\n                    printf(\"[|cFF40FB40%s|r] \"..rhoninStartTip, rhoninName, settings.yelled_times_today)\n                elseif (wordIndex == #rhoninYellSpeeches) then\n                    printf(\"[|cFF40FB40%s|r] \"..rhoninEndTip, rhoninName, settings.yelled_times_today)\n                end\n                \n                if NeedShoutUpRhoninYell() then\n                    needBlocked = true\n                end\n                \n                if NeedShoutUpRhoninVoice() then\n                    MuteRhoninSoundFiles(true)\n                else\n                    if (wordIndex == #rhoninYellSpeeches) then\n                        settings.next_random = random(100)\n                        settings.allowed_yell_times_today = settings.allowed_yell_times_today + 1\n                    end\n                    MuteRhoninSoundFiles(false)\n                end\n            end\n            \n            -- SetCVar(\"Sound_EnableDialog\", 0)\n            -- SetCVar(\"Sound_EnableDialog\", 1)\n        end\n        \n        settings.lastBlocked = needBlocked\n        return needBlocked\n    else\n        return settings.lastBlocked\n    end\nend\n\nlocal function ChatFrame_InitFilter(event, filter, toggle)\n    assert(event)\n    settings.cur_filter[event] = settings.cur_filter[event] or nil\n    \n    local db = _G[\"WA_\"..aura_env.id] or {}\n    \n    db.chatFilters = db.chatFilters or {}\n    db.chatFilters[event] = db.chatFilters[event] or {}\n    \n    assert(filter)\n    local exists = false\n    local match_index = -1\n    for index, fnFilter in next, db.chatFilters[event] do\n        if filter == fnFilter then\n            exists = true\n            match_index = index\n            break\n        end\n    end\n    \n    if toggle then\n        if not exists then\n            for index, fnFilter in next, db.chatFilters[event] do\n                if fnFilter ~= nil then\n                    ChatFrame_RemoveMessageEventFilter(event, fnFilter)\n                    table_remove(db.chatFilters[event], index)\n                end\n            end\n            \n            ChatFrame_AddMessageEventFilter(event, filter)\n            settings.cur_filter[event] = filter\n            table_insert(db.chatFilters[event], filter)\n        end\n    else\n        if exists then\n            ChatFrame_RemoveMessageEventFilter(event, filter)\n            \n            --settings.cur_filter[event] = nil\n            if match_index > 0 then\n                table_remove(db.chatFilters[event], match_index)\n            end\n        end\n    end\nend\n\nlocal function ChatFrame_InitFilters(toggle)\n    ChatFrame_InitFilter(\"CHAT_MSG_MONSTER_YELL\", ChatFrame_NonsterYellFilter, toggle)\n    --ChatFrame_InitFilter(\"CHAT_MSG_MONSTER_SAY\",  ChatFrame_NonsterYellFilter, toggle)\nend\n\n--\n-- Events: PLAYER_ENTERING_WORLD, PLAYER_LEAVING_WORLD, PLAYER_LOGIN, PLAYER_LOGOUT, OPTIONS, OPTIONS_CLOSE\n--\nenv.OnTrigger = function(allstates, event, ...)\n    if event == \"PLAYER_LOGIN\" or event == \"PLAYER_ENTERING_WORLD\" then\n        MuteRhoninVoiceIfNeed()\n        if not env.loaded then\n            LoadSession()\n            ChatFrame_InitFilters(true)\n            env.loaded = true\n        end\n        return true\n        \n    elseif event == \"OPTIONS\" then\n        SyncOptions(allstates)\n        if WeakAuras.IsOptionsOpen() and env.initialized then\n            env.initialized = false\n        end\n        return true\n        \n    elseif event == \"OPTIONS_CLOSE\" then\n        SyncOptions(allstates)\n        env.initialized = true\n        SaveSession()\n        return true\n        \n    elseif event == \"STATUS\" then\n        SyncOptions(allstates)\n        if WeakAuras.IsOptionsOpen() and env.initialized then\n            env.initialized = false\n        else\n            env.initialized = true\n            SaveSession()\n        end\n        return true\n        \n    elseif env.initialized then\n        if event == \"PLAYER_LOGOUT\" or event == \"PLAYER_LEAVING_WORLD\" then\n            MuteRhoninVoiceIfNeed()\n            ChatFrame_InitFilters(false)\n            SaveSession()\n            env.loaded = false\n            return true\n        end\n    end\nend",
["do_custom"] = true,
},
},
