            iNextEncounter = 633,\n            },\n            [633] = { -- 633 - Jaraxxus\n                [\"A\"] = {\n                    sNPCID = \"34780\",\n                    sTarName = \"Lord Jaraxxus\",\n                    iIcon = 136172,\n                    tEnabledOptions = {\n                        \"bJaraxxusFight\", \n                        \"bJaraxxus\",\n                    },\n                },\n                [\"B\"] = {   \n                    sNPCID = \"34825\",\n                    sTarName = \"Nether Portal\",\n                    iIcon = 237560,  \n                    tEnabledOptions = {\n                        \"bJaraxxusFight\", \n                        \"bNetherPortal\",\n                    },\n                },\n                [\"C\"] = {     \n                    sNPCID = \"34813\",\n                    sTarName = \"Infernal Volcano\",\n                    iIcon = 135830,\n                    tEnabledOptions = {\n                        \"bJaraxxusFight\", \n                        \"bInfernalVolcano\",\n                    },\n                },\n                [\"D\"] = {     \n                    sNPCID = \"34826\",\n                    sTarName = \"Mistress of Pain\",\n                    iIcon = 136220,\n                    tEnabledOptions = {\n                        \"bJaraxxusFight\", \n                        \"bMistressOfPain\",\n                    },\n                },\n                iNextEncounter = 637,\n            },\n            [637] = { -- 637 - Faction Champions\n                [\"A\"] = {\n                    sNPCID = bIsHorde and \"34463\" or \"34455\",\n                    sTarName = bIsHorde and \"Shaabad\" or \"Broln Stouthorn\",\n                    iIcon = 136051,\n                    tEnabledOptions = {\n                        \"bChampionsFight\", \n                        \"bChampionsEnh\",\n                    },\n                },\n                [\"B\"] = {\n                    sNPCID = b