["【术士】丢地狱火提示（by drepguy）"] = {
["iconSource"] = -1,
["wagoID"] = "aY07-5RHu",
["authorOptions"] = {
},
["preferToUpdate"] = false,
["yOffset"] = -29.61894887288412,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["url"] = "https://space.bilibili.com/455259",
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["events"] = "UNIT_HEALTH:target",
["custom"] = "function()    \n    if WeakAuras.IsOptionsOpen() then return false end\n    \n    -- only calculate if targeted a boss\n    if UnitLevel(\"target\") ~= -1 then return false end\n    \n    -- get hp and time\n    local currenthealth = UnitHealth(\"target\")\n    local currenttime = GetTime()\n    \n    -- are we at 100% ? then reset variables\n    if currenthealth == UnitHealthMax(\"target\") then\n        aura_env.health0, aura_env.time0, aura_env.time = nil, nil, nil\n        return false\n    end\n    \n    -- initial setup of variables health0 and time0, which is our important reference point\n    if not aura_env.health0 then\n        aura_env.health0, aura_env.time0 = currenthealth, currenttime\n        return false\n    end\n    \n    if currenthealth >= aura_env.health0 then\n        -- this is fojjis try resetting variables but this does not always work\n        -- for example switching targets from high hp mob to lower hp mob, better reset\n        -- these variables in diffrent trigger e.g. on target change\n        aura_env.health0, aura_env.time0, aura_env.time = nil, nil, nil\n    else\n        -- remaining time whould be better wording\n        aura_env.time = currenthealth * (aura_env.time0 - currenttime) / (currenthealth - aura_env.health0)\n    end\n    \n    if not aura_env.time then\n        return false\n    end\n    \n    if (aura_env.time <= 65 and aura_env.time >= 45) then\n        return true\n    else\n        return false\n    end\nend",
["spellIds"] = {
},
["names"] = {
},
["check"] = "update",
["subeventPrefix"] = "SPELL",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "custom",
},
["untrigger"] = {
["custom"] = "function()    \n    if (aura_env.time == nil) then\n        return true\n    end\n    \n    -- print(\"untrig \" .. aura_env.time)\n    \n    if (aura_env.time <= 65 and aura_env.time >= 45) then\n        return false\n    else\n        return true\n    end\n    \nend\n\n\n\n",
},
},
