,\n    [\"Vivienne Blackwhisper\"] = \"暗语者维维尼\",\n    [\"Noozle Whizzlestick\"] = \"努兹尔·啸钉\",\n    [\"Ginselle Blightslinger\"] = \"凋零者吉塞尔\",\n    [\"Fjola Lightbane\"] = \"光明邪使菲奥拉\",\n    [\"Eydis Darkbane\"] = \"黑暗邪使艾蒂丝\",\n    [\"The Icy Depths\"] = \"寒冰深渊\",\n    [\"Anub'arak\"] = \"阿努巴拉克\",\n    [\"Nerubian Burrower\"] = \"蛛魔掘地者\",\n    [\"Onyxia's Lair\"] = \"奥妮克希亚的巢穴\",\n    [\"Onyxia\"] = \"奥妮克希亚\",\n    [\"Onyxian Lair Guard\"] = \"奥妮克希亚巢穴守卫\",\n    -- ICC\n    [\"The Spire\"] = \"冰冠之塔\",\n    [\"Lord Marrowgar\"] = \"玛洛加尔领主\",\n    [\"Bone Spike\"] = \"骨针\",\n    [\"Oratory of the Damned\"] = \"诅咒祷堂\",\n    [\"Lady Deathwhisper\"] = \"亡语者女士\",\n    [\"Cult Adherent\"] = \"教派追随者\",\n    [\"Cult Fanatic\"] = \"教派狂热者\",\n    [\"Rampart of Skulls\"] = \"颅骨之墙\",\n    [\"Muradin Bronzebeard\"] = \"穆拉丁·铜须\",\n    [\"High Overlord Saurfang\"] = \"萨鲁法尔大王\",\n    [\"Deathbringer's Rise\"] = \"死亡使者的高台\",\n    [\"Deathbringer Saurfang\"] = \"死亡使者萨鲁法尔\",\n    [\"Blood Beast\"] = \"血兽\",\n    [\"The Plagueworks\"] = \"天灾工厂\",\n    [\"Festergut\"] = \"烂肠\",\n    [\"Rotface\"] = \"腐面\",\n    [\"Little Ooze\"] = \"小软泥怪\",\n    [\"Putricide's Laboratory of Alchemical Horrors and Fun\"] = \"普崔赛德的恐怖和娱乐化学实验室\",\n    [\"Volatile Ooze\"] = \"不稳定的软泥怪\",\n    [\"Professor Putricide\"] = \"普崔塞德教授\",\n    [\"Gas Cloud\"] = \"毒气之云\",\n    [\"The Crimson Hall\"] = \"血色厅堂\",\n    [\"Prince Taldaram\"] = \"塔达拉姆王子\",\n    [\"Prince Keleseth\"] = \"凯雷塞斯王子\",\n    [\"Prince Valanar\"] = \"瓦拉纳王子\",\n    [\"The Sanctum of Blood\"] = \"鲜血秘室\",\n    [\"Blood-Queen Lana'thel\"] = \"鲜血女王兰娜瑟尔\",\n    [\"The Frostwing Halls\"] = \"霜翼大厅\",\n    [\"Valithria Dreamwalker\"] = \"踏梦者瓦莉瑟瑞娅\",\n    [\"Gluttonous Abomination\"] = \"贪食的憎恶\",\n    [\"Risen Archmage\"] = \"复生的大法师\",\n    [\"Suppresser\"] = nil,\n    [\"The Frost Queen's Lair\"] = \"冰霜女王的巢穴\",\n    [\"Sindragosa\"] = \"辛达苟萨\",\n    [\"The Frozen Throne\"] = \"冰封王座\",\n    [\"The Lich King\"] = \"巫妖王\",\n    [\"Shambling Horror\"] = \"蹒跚的血僵尸\",\n    [\"Ice Sphere\"] = \"寒冰之球\",\n    [\"Raging Spirit\"] = nil,\n    [\"Val'kyr Shadowguard\"] = nil,\n}\n\n\n\nlocal function LocalizeTable(tTableToLocalize)\n    if tTableToLocalize.bLocalized then return tTableToLocalize end\n    \n    local tLocalizedTable = {\n        bLocalized = GetLocale(),\n        \n    }\n    \n    local function LocalizeField(tIn, tOut, sKey)\n        local sLocalizedKey = sKey\n        if tLocData.tLocalizations[sKey] and tLocData.tLocalizations[sKey] then\n            sLocalizedKey = tLocData.tLocalizations[sKey]\n        end\n        \n        if type(tIn[sKey]) == \"table\" then\n            tOut[sLocalizedKey] = {}\n            \n            for k,_ in pairs(tIn[sKey]) do\n                LocalizeField(tIn[sKey], tOut[sLocalizedKey], k)\n            end\n        else\n            if tLocData.tLocalizations[tIn[sKey]] and tLocData.tLocalizations[tIn[sKey]] then\n                tOut[sLocalizedKey] = tLocData.tLocalizations[tIn[sKey]]\n            else\n                tOut[sLocalizedKey] = tIn[sKey]\n            end\n        end\n    end\n    \n    for k,_ in pairs(tTableToLocalize) do\n        LocalizeField(tTableToLocalize, tLocalizedTable, k)\n    end\n    \n    return tLocalizedTable\nend\ntLocData.fnLocalizeTable = LocalizeTable\n\nlocal function InitLoca()\n    if GetLocale() == aura_env.sLocale then\n        WeakAuras.ScanEvents(\"MultiDotFrame_Localize\", tLocData)\n    end\nend\naura_env.fnInitLoca = InitLoca\n\nInitLoca()",
["do_custom"] = true,
